const rtdal000263Source0001 = `bs_theme <- function(
  version = version_default(),
  preset = NULL,
  ...,
  brand = NULL,
  bg = NULL,
  fg = NULL,
  primary = NULL,
  secondary = NULL,
  success = NULL,
  info = NULL,
  warning = NULL,
  danger = NULL,
  base_font = NULL,
  code_font = NULL,
  heading_font = NULL,
  font_scale = NULL,
  bootswatch = NULL
) {
  is_version_from_user <- !missing(version)

  brand <- brand_resolve(brand)

  preset <-
    if (!is.null(brand)) {
      brand_resolve_preset(
        brand = brand,
        preset = preset,
        version = if (is_version_from_user) version
      )
    } else {
      if (is.null(preset) && is.null(bootswatch) && version >= 5) {
        preset <- "shiny"
      }
      resolve_bs_preset(preset, bootswatch, version = version)
    }

  version <- preset$version %||% version %||% version_default()

  bundle <- bs_bundle(
    bs_theme_init(version),
    bootstrap_bundle(version),
    bs_preset_bundle(preset),
    bs_brand_bundle(brand, version = version)
  )

  if (!is.null(preset$type)) {
    bundle <- add_class(bundle, THEME_PRESET_CLASS)
  }

  bundle <- bs_theme_update(
    bundle,
    ...,
    bg = bg,
    fg = fg,
    primary = primary,
    secondary = secondary,
    success = success,
    info = info,
    warning = warning,
    danger = danger,
    base_font = base_font,
    code_font = code_font,
    heading_font = heading_font,
    font_scale = font_scale
  )

  if (!is.null(brand)) {
    bundle <- add_class(bundle, "bs_theme_brand")
    attr(bundle, "brand") <- brand
  }

  bundle
}`

const rtdal000263Source0002 = `bs_theme_update <- function(
  theme,
  ...,
  preset = NULL,
  bg = NULL,
  fg = NULL,
  primary = NULL,
  secondary = NULL,
  success = NULL,
  info = NULL,
  warning = NULL,
  danger = NULL,
  base_font = NULL,
  code_font = NULL,
  heading_font = NULL,
  font_scale = NULL,
  bootswatch = NULL
) {
  assert_bs_theme(theme)

  preset <- resolve_bs_preset(
    preset,
    bootswatch,
    version = theme_version(theme)
  )

  if (!is.null(preset)) {
    theme_has_preset <- inherits(theme, THEME_PRESET_CLASS)

    if (theme_has_preset) {
      # remove the old preset
      theme <- bs_remove(theme, theme_preset_info(theme)$type)
      class(theme) <- setdiff(class(theme), THEME_PRESET_CLASS)
    }

    # Add in the new preset unless vanilla bootstrap was requested
    if (!identical(preset$name, "bootstrap")) {
      theme <- add_class(theme, THEME_PRESET_CLASS)
      theme <- bs_bundle(theme, bs_preset_bundle(preset))
    }
  }

  # See R/bs-theme-update.R for the implementation of these
  theme <- bs_base_colors(theme, bg = bg, fg = fg)
  theme <- bs_accent_colors(
    theme,
    primary = primary,
    secondary = secondary,
    success = success,
    info = info,
    warning = warning,
    danger = danger
  )
  theme <- bs_fonts(
    theme,
    base = base_font,
    code = code_font,
    heading = heading_font
  )
  if (!is.null(font_scale)) {
    stopifnot(is.numeric(font_scale) && length(font_scale) == 1)
    theme <- bs_add_variables(
      theme,
      "font-size-base" = paste(
        font_scale,
        "*",
        bs_get_variables(theme, "font-size-base")
      )
    )
  }
  bs_add_variables(theme, ...)
}`

const rtdal000263Source0003 = `bs_global_theme_update <- function(
  ...,
  preset = NULL,
  bg = NULL,
  fg = NULL,
  primary = NULL,
  secondary = NULL,
  success = NULL,
  info = NULL,
  warning = NULL,
  danger = NULL,
  base_font = NULL,
  code_font = NULL,
  heading_font = NULL,
  bootswatch = NULL
) {
  theme <- assert_global_theme("bs_theme_global_update()")
  bs_global_set(
    bs_theme_update(
      theme,
      ...,
      preset = preset,
      bootswatch = bootswatch,
      bg = bg,
      fg = fg,
      primary = primary,
      secondary = secondary,
      success = success,
      info = info,
      warning = warning,
      danger = danger,
      base_font = base_font,
      code_font = code_font,
      heading_font = heading_font
    )
  )
}`

const rtdal000263Source0011 = `bs3compat_bundle <- function() {
  sass_layer(
    defaults = sass_file(
      system_file("bs3compat", "_defaults.scss", package = "bslib")
    ),
    mixins = sass_file(
      system_file("bs3compat", "_declarations.scss", package = "bslib")
    ),
    rules = sass_file(
      system_file("bs3compat", "_rules.scss", package = "bslib")
    ),
    # Gyliphicon font files
    file_attachments = c(
      fonts = path_lib("bs3", "assets", "fonts")
    ),
    html_deps = htmltools::htmlDependency(
      "bs3compat",
      packageVersion("bslib"),
      package = "bslib",
      src = "bs3compat/js",
      script = c("transition.js", "tabs.js", "bs3compat.js")
    )
  )
}`

const rtdal000263Source0012 = `bs3_accessibility_bundle <- function() {
  sass_layer(
    rules = sass_file(
      system_file(
        "lib",
        "bs-a11y-p",
        "src",
        "sass",
        "bootstrap-accessibility.scss",
        package = "bslib"
      )
    ),
    html_deps = htmltools::htmlDependency(
      "bootstrap-accessibility",
      version_accessibility,
      package = "bslib",
      src = "lib/bs-a11y-p",
      script = "plugins/js/bootstrap-accessibility.min.js",
      all_files = FALSE
    )
  )
}`

