const rtdal000265Source0001 = `input_task_button <- function(
  id,
  label,
  ...,
  icon = NULL,
  label_busy = "Processing...",
  icon_busy = rlang::missing_arg(),
  type = "primary",
  auto_reset = TRUE
) {
  dots <- separate_arguments(...)
  attribs <- dots$attribs
  children <- dots$children

  icon_busy <- rlang::maybe_missing(
    icon_busy,
    fontawesome::fa_i("refresh", class = "fa-spin", "aria-hidden" = "true")
  )

  tags$button(
    id = id,
    class = if (!is.null(type)) paste0("btn btn-", type),
    class = "bslib-task-button",
    type = "button",
    "data-auto-reset" = if (isTRUE(auto_reset)) NA else NULL,
    !!!attribs,

    component_dependencies(),

    htmltools::tag(
      "bslib-switch-inline",
      rlang::list2(
        case = "ready",
        span(slot = "ready", icon, label),
        span(slot = "busy", icon_busy, label_busy),
        !!!children
      )
    )
  )
}`

const rtdal000265Source0002 = "update_task_button <- function(\n  id,\n  ...,\n  state = NULL,\n  session = get_current_session()\n) {\n  force(id)\n  force(state)\n\n  rlang::check_dots_empty()\n\n  if (!is.null(state)) {\n    if (!rlang::is_string(state)) {\n      abort(\"`state` must be a single character value.\")\n    }\n    set_task_button_manual_reset(\n      session,\n      id,\n      manual = !identical(state, \"ready\")\n    )\n  }\n\n  session$sendInputMessage(id, dropNulls(list(state = state)))\n}"

const rtdal000265Source0003 = `task_button_manual_reset_map <- function(session) {
  key <- "manual_task_button_reset"
  map <- session$userData[[key]]
  if (is.null(map)) {
    map <- fastmap::fastmap()
    session$userData[[key]] <- map
  }
  map
}`

const rtdal000265Source0004 = `set_task_button_manual_reset <- function(session, id, manual = TRUE) {
  ns_id <- session$ns(id)
  map <- task_button_manual_reset_map(session)
  if (isTRUE(manual)) {
    map$set(ns_id, TRUE)
  } else {
    map$remove(ns_id)
  }
}`

const rtdal000265Source0005 = `is_task_button_manual_reset <- function(session, id) {
  ns_id <- session$ns(id)
  map <- task_button_manual_reset_map(session)
  map$get(ns_id, FALSE)
}`

const rtdal000265Source0006 = `input_task_button_input_handler <- function(val, shinysession, name) {
  value <- val[["value"]]

  if (isTRUE(val[["autoReset"]])) {
    shinysession$onFlush(once = TRUE, function() {
      # This is input_task_button's auto-reset feature: unless the button has
      # opted out using set_task_button_manual_reset(), we should reset after
      # a flush cycle where a bslib.taskbutton value is seen.
      if (!is_task_button_manual_reset(shinysession, name)) {
        update_task_button(name, state = "ready", session = shinysession)
      }
    })
  }

  # mark up the action button value with a special class so we can recognize it later
  class(value) <- c("shinyActionButtonValue", class(value))
  value
}`

const rtdal000265Source0007 = `bind_task_button <- function(target, task_button_id, ...) {
  UseMethod("bind_task_button")
}`

const rtdal000265Source0008 = `bind_task_button.default <- function(target, task_button_id, ...) {
  abort(
    "Don't know how to bind a task button to an object of class '",
    class(target)[[0]],
    "'"
  )
}`

const rtdal000265Source0009 = `bind_task_button.ExtendedTask <- function(
  target,
  task_button_id,
  ...,
  session = get_current_session()
) {
  force(target)
  force(task_button_id)
  force(session)

  was_running <- FALSE
  shiny::observe(
    label = "update_task_button_state",
    {
      running <- target$status() == "running"
      if (running != was_running) {
        was_running <<- running
        if (running) {
          update_task_button(task_button_id, state = "busy", session = session)
        } else {
          update_task_button(task_button_id, state = "ready", session = session)
        }
      }
    },
    priority = 1000
  )
  return(target)
}`

