const rtdal000269Source0004 = `fill_dependency <- local({
  fill_dep <- NULL

  function() {
    if (!is.null(fill_dep)) {
      return(fill_dep)
    }
    fill_dep <<- htmltools::findDependencies(
      htmltools::bindFillRole(htmltools::tags$div(), container = TRUE)
    )[[1]]
    fill_dep
  }
})`

const rtdal000269Source0006 = "warn_css_selector_null <- function(x) {\n  if (is.null(x)) {\n    return()\n  }\n\n  rlang::warn(\n    \"Ignoring non-NULL `css_selector` because an input tag `x` was not provided.\",\n    call = rlang::caller_env()\n  )\n}"

const rtdal000269Source0015 = `renders_to_tag_class <- function(x, class, selector = NULL) {
  x <- try(as.tags(x), silent = TRUE)
  if (inherits(x, "try-error")) {
    return(FALSE)
  }
  xq <- tagQuery(x)
  if (length(selector)) {
    xq <- xq$find(selector)
  }
  vapply(
    xq$selectedTags(),
    function(y) tagQuery(y)$hasClass(class),
    logical(1),
    USE.NAMES = FALSE
  )
}`

