const rtdal000280Source0001 = `navset_card_tab <- function(
  ...,
  id = NULL,
  selected = NULL,
  title = NULL,
  sidebar = NULL,
  header = NULL,
  footer = NULL,
  height = NULL,
  full_screen = FALSE,
  wrapper = card_body
) {
  navset_card(
    navset_tab,
    "card-header-tabs",
    ...,
    id = id,
    selected = selected,
    title = title,
    sidebar = sidebar,
    header = header,
    footer = footer,
    height = height,
    full_screen = full_screen,
    wrapper = wrapper
  )
}`

const rtdal000280Source0002 = `navset_card_pill <- function(
  ...,
  id = NULL,
  selected = NULL,
  title = NULL,
  sidebar = NULL,
  header = NULL,
  footer = NULL,
  height = NULL,
  placement = c("above", "below"),
  full_screen = FALSE,
  wrapper = card_body
) {
  items <- collect_nav_items(..., wrapper = wrapper)

  pills <- navset_pill(!!!items, id = id, selected = selected)

  above <- match.arg(placement) == "above"

  pillQ <- tagQuery(pills)

  # https://getbootstrap.com/docs/5.0/components/card/#navigation
  nav <- pillQ$children(".nav")$addClass(
    if (above) "card-header-pills"
  )$selectedTags()[[1]]
  content <- pillQ$children(".tab-content")$selectedTags()[[1]]

  nav_args <- if (!is.null(title)) {
    list(class = "bslib-navs-card-title", tags$span(title), nav)
  } else {
    list(nav)
  }

  card(
    height = height,
    full_screen = full_screen,
    if (above) card_header(!!!nav_args),
    header,
    navs_card_body(content, sidebar),
    footer,
    if (!above) card_footer(!!!nav_args)
  )
}`

const rtdal000280Source0003 = `navset_card_underline <- function(
  ...,
  id = NULL,
  selected = NULL,
  title = NULL,
  sidebar = NULL,
  header = NULL,
  footer = NULL,
  height = NULL,
  full_screen = FALSE,
  wrapper = card_body
) {
  navset_card(
    navset_underline,
    "nav-underline",
    ...,
    id = id,
    selected = selected,
    title = title,
    sidebar = sidebar,
    header = header,
    footer = footer,
    height = height,
    full_screen = full_screen,
    wrapper = wrapper
  )
}`

const rtdal000280Source0004 = `navset_card <- function(
  navset_func,
  nav_class,
  ...,
  id,
  selected,
  title,
  sidebar,
  header,
  footer,
  height,
  full_screen,
  wrapper
) {
  items <- collect_nav_items(..., wrapper = wrapper)

  tabs <- navset_func(!!!items, id = id, selected = selected)

  tabQ <- tagQuery(tabs)

  # https://getbootstrap.com/docs/5.3/components/card/#navigation
  nav <- tabQ$children(".nav")$addClass(nav_class)$selectedTags()[[1]]
  content <- tabQ$children(".tab-content")$selectedTags()[[1]]

  card(
    height = height,
    full_screen = full_screen,
    if (!is.null(title)) {
      card_header(class = "bslib-navs-card-title", tags$span(title), nav)
    } else {
      card_header(nav)
    },
    header,
    navs_card_body(content, sidebar),
    footer
  )
}`

const rtdal000280Source0005 = `collect_nav_items <- function(..., wrapper) {
  items <- rlang::list2(...)

  # Wrap any nav_panel() children up into card items
  nav_to_card_item <- function(x) {
    if (isNavbarMenu(x)) {
      x$tabs <- lapply(x$tabs, nav_to_card_item)
    }
    if (isTabPanel(x)) {
      x$children <- as_card_items(x$children, wrapper = wrapper)
    }
    x
  }

  lapply(items, nav_to_card_item)
}`

const rtdal000280Source0007 = "makeTabsFillable <- function(\n  content,\n  fillable = TRUE,\n  navbar = FALSE,\n  gap = NULL,\n  padding = NULL\n) {\n  if (\n    !inherits(content, \"shiny.tag\") ||\n      !tagQuery(content)$hasClass(\"tab-content\")\n  ) {\n    abort(\"Expected `content` to be a tag with a tab-content class\")\n  }\n\n  if (isFALSE(fillable)) {\n    return(content)\n  }\n\n  # Even if only one .tab-pane wants fillable behavior, the .tab-content\n  # must to be a fillable container.\n  content <- bindFillRole(content, container = TRUE, item = TRUE)\n\n  tagQuery(content)$find(\".tab-pane\")$each(function(x, i) {\n    if (\n      isTRUE(fillable) || isTRUE(tagGetAttribute(x, \"data-value\") %in% fillable)\n    ) {\n      x <- tagAppendAttributes(\n        class = \"bslib-gap-spacing\",\n        style = css(\n          # Remove the margin between nav and content (for page_navbar())\n          \"--bslib-navbar-margin\" = if (navbar) 0,\n          gap = gap,\n          padding = padding\n        ),\n        bindFillRole(x, container = TRUE, item = TRUE)\n      )\n    }\n\n    x\n  })$allTags()\n}"

