const rtdal000295Source0003 = `tag_add_outer_class <- function(x, class = NULL, ...) {
  if (is.null(class)) {
    return(x)
  }

  if (inherits(x, "shiny.tag")) {
    return(tagAppendAttributes(x, class = class, ...))
  }

  as_fill_carrier(div(x, class = class, ...))
}`

