const rtdal000317Source0009 = "test_that(\"input_code_editor handles empty `value`\", {\n  editor <- input_code_editor(\"empty_editor\", value = \"\")\n\n  html <- as.character(editor)\n  expect_match(html, 'value=\"\"')\n})"

