const rtdal000319Source0001 = `test_that("layout_columns() with col_widths", {
  children <- lapply(1:2, function(...) {
    div(class = "layout-column-child-element")
  })

  expect_snapshot(
    layout_columns(col_widths = 6, !!!children)
  )

  expect_snapshot(
    layout_columns(col_widths = c(4, 8), !!!children)
  )

  expect_snapshot(
    layout_columns(
      col_widths = breakpoints(sm = 6, md = 4, lg = 3),
      !!!children
    )
  )

  expect_snapshot(
    layout_columns(col_widths = breakpoints(sm = NA, lg = c(4, 8)), !!!children)
  )

  expect_snapshot(
    layout_columns(
      col_widths = breakpoints(sm = NA, lg = c(4, -4, 4)),
      !!!children
    )
  )
})`

const rtdal000319Source0002 = "test_that(\"layout_columns() without `col_widths`\", {\n  expect_no_match(\n    format(layout_columns(div())),\n    \"col-widths-\"\n  )\n\n  expect_no_match(\n    format(layout_columns(div(), col_widths = NULL)),\n    \"col-widths-\"\n  )\n\n  expect_no_match(\n    format(layout_columns(div(), col_widths = list(NA))),\n    \"col-widths-\"\n  )\n})"

