const rtdal000321Source0005 = "test_that(\"navbar markup snapshots\", {\n  expect_snapshot(\n    show_navbar_markup(navs_bar_(theme = bs_theme(version = 3)))\n  )\n\n  expect_snapshot(\n    show_navbar_markup(navs_bar_(theme = bs_theme(version = 4)))\n  )\n\n  expect_snapshot(\n    show_navbar_markup(navs_bar_(theme = bs_theme(version = 5)))\n  )\n\n  expect_snapshot(\n    show_navbar_markup(\n      navs_bar_(\n        theme = bs_theme(version = 4),\n        navbar_options = navbar_options(theme = \"dark\")\n      )\n    )\n  )\n\n  expect_snapshot(\n    show_navbar_markup(\n      navs_bar_(\n        theme = bs_theme(version = 4),\n        navbar_options = navbar_options(theme = \"light\")\n      )\n    )\n  )\n\n  expect_snapshot(\n    show_navbar_markup(\n      navs_bar_(\n        theme = bs_theme(version = 4),\n        navbar_options = navbar_options(bg = \"#000\")\n      )\n    )\n  )\n\n  expect_snapshot(\n    show_navbar_markup(\n      navs_bar_(\n        theme = bs_theme(version = 5),\n        navbar_options = navbar_options(theme = \"dark\")\n      )\n    )\n  )\n\n  expect_snapshot(\n    show_navbar_markup(\n      navs_bar_(\n        theme = bs_theme(version = 5),\n        navbar_options = navbar_options(theme = \"light\")\n      )\n    )\n  )\n\n  expect_snapshot(\n    show_navbar_markup(\n      navs_bar_(\n        theme = bs_theme(version = 5),\n        navbar_options = navbar_options(bg = \"#000\")\n      )\n    )\n  )\n\n  expect_snapshot(\n    show_navbar_markup(\n      navs_bar_(\n        theme = bs_theme(version = 5),\n        navbar_options = navbar_options(\n          theme = \"light\",\n          `data-bs-theme` = \"dark\"\n        )\n      )\n    )\n  )\n\n  expect_snapshot(\n    show_navbar_markup(\n      navs_bar_(\n        theme = bs_theme(version = 5),\n        navbar_options = navbar_options(class = \"bg-primary\", theme = \"dark\")\n      )\n    )\n  )\n})"

