const rtdal000323Source0004 = `test_that("save_html() works on components and pages with a custom theme", {
  withr::with_tempdir({
    withr::local_options(list(htmltools.dir.version = FALSE))
    save_html(
      card("A simple card"),
      "card.html"
    )
    expect_snapshot_file("card.html")
  })

  withr::with_tempdir({
    withr::local_options(list(htmltools.dir.version = FALSE))
    save_html(
      page(
        theme = bs_remove(bs_theme(), "bs3compat"),
        "A simple page without bs3compat dependencies"
      ),
      "modern-page.html"
    )
    expect_snapshot_file("modern-page.html")
  })
})`

