const rtdal000328Source0001 = "test_that(\"bs4 base colors\", {\n  varnames <- c(\n    \"black\",\n    \"white\",\n    paste0(\"gray-\", 1:9 * 100),\n    \"body-bg\",\n    \"body-color\",\n    \"primary\",\n    \"secondary\"\n  )\n\n  theme <- bs_theme(\n    4,\n    bg = \"white\",\n    fg = \"black\",\n    primary = \"blue\",\n    secondary = \"silver\"\n  )\n  colors <- bs_get_variables(theme, varnames)\n\n  expect_identical(\n    colors,\n    c(\n      black = \"#000000\",\n      white = \"#FFFFFF\",\n      `gray-100` = \"#E6E6E6\",\n      `gray-200` = \"#CCCCCC\",\n      `gray-300` = \"#B2B2B2\",\n      `gray-400` = \"#999999\",\n      `gray-500` = \"#808080\",\n      `gray-600` = \"#666666\",\n      `gray-700` = \"#4D4D4D\",\n      `gray-800` = \"#333333\",\n      `gray-900` = \"#191919\",\n      `body-bg` = \"#FFFFFF\",\n      `body-color` = \"#191919\",\n      primary = \"#0000FF\",\n      secondary = \"#C0C0C0\"\n    )\n  )\n\n  theme <- bs_theme(\n    \"4\",\n    bg = \"#112233\",\n    fg = \"#FFEEDD\",\n    primary = \"orange\",\n    secondary = \"brown\"\n  )\n  colors <- bs_get_variables(theme, varnames)\n\n  expect_identical(\n    colors,\n    c(\n      black = \"#FFEEDD\",\n      white = \"#112233\",\n      `gray-100` = \"#293644\",\n      `gray-200` = \"#414B55\",\n      `gray-300` = \"#585F66\",\n      `gray-400` = \"#707477\",\n      `gray-500` = \"#888888\",\n      `gray-600` = \"#A09C99\",\n      `gray-700` = \"#B8B1AA\",\n      `gray-800` = \"#CFC5BB\",\n      `gray-900` = \"#E7DACC\",\n      `body-bg` = \"#112233\",\n      `body-color` = \"#E7DACC\",\n      primary = \"#FFA500\",\n      secondary = \"#A52A2A\"\n    )\n  )\n\n  # Can individual colors still be overridden?\n  theme <- bs_add_variables(theme, \"body-bg\" = \"white\", black = \"red\")\n  expect_identical(\n    bs_get_variables(theme, c(\"body-bg\", \"black\")),\n    c(\"body-bg\" = \"white\", black = \"red\")\n  )\n})"

const rtdal000328Source0002 = "test_that(\"bs3 base colors\", {\n  varnames <- c(\n    \"gray-base\",\n    \"white\",\n    paste0(\"gray\", c(\"-darker\", \"-dark\", \"\", \"-light\", \"-lighter\")),\n    \"body-bg\",\n    \"text-color\",\n    \"brand-primary\"\n  )\n\n  theme <- bs_theme(\"3\", bg = \"white\", fg = \"black\", primary = \"blue\")\n  colors <- bs_get_variables(theme, varnames)\n\n  expect_identical(\n    colors,\n    c(\n      `gray-base` = \"#000000\",\n      white = \"#FFFFFF\",\n      `gray-darker` = \"#222222\",\n      `gray-dark` = \"#333333\",\n      gray = \"#555555\",\n      `gray-light` = \"#777777\",\n      `gray-lighter` = \"#EEEEEE\",\n      `body-bg` = \"#FFFFFF\",\n      `text-color` = \"#333333\",\n      `brand-primary` = \"#0000FF\"\n    )\n  )\n\n  expect_warning(\n    theme <- bs_theme(\n      \"3\",\n      bg = \"#112233\",\n      fg = \"#FFEEDD\",\n      primary = \"orange\",\n      secondary = \"brown\"\n    ),\n    \"doesn't support.*ignored\"\n  )\n  colors <- bs_get_variables(theme, varnames)\n\n  expect_identical(\n    colors,\n    c(\n      `gray-base` = \"#FFEEDD\",\n      white = \"#112233\",\n      `gray-darker` = \"#DFD3C6\",\n      `gray-dark` = \"#CFC5BB\",\n      gray = \"#B0AAA4\",\n      `gray-light` = \"#908F8E\",\n      `gray-lighter` = \"#21303E\",\n      `body-bg` = \"#112233\",\n      `text-color` = \"#CFC5BB\",\n      `brand-primary` = \"#FFA500\"\n    )\n  )\n\n  # Can individual colors still be overridden?\n  theme <- bs_add_variables(theme, \"body-bg\" = \"black\")\n  expect_identical(\n    bs_get_variables(theme, c(\"body-bg\", \"gray-darker\")),\n    c(\"body-bg\" = \"black\", \"gray-darker\" = \"#DFD3C6\")\n  )\n})"

const rtdal000328Source0003 = `test_that("bs4 accent colors", {
  varnames <- c("primary", "secondary", "success", "info", "warning", "danger")

  # Baseline
  theme <- bs_theme(4)
  expect_identical(
    bs_get_variables(theme, varnames),
    c(
      primary = "#007bff",
      secondary = "#6c757d",
      success = "#28a745",
      info = "#17a2b8",
      warning = "#ffc107",
      danger = "#dc3545"
    )
  )

  theme <- bs_theme(
    4,
    primary = "#123",
    secondary = "#234",
    success = "#345",
    info = "#456",
    warning = "#567",
    danger = "#678"
  )
  expect_identical(
    bs_get_variables(theme, varnames),
    c(
      primary = "#112233",
      secondary = "#223344",
      success = "#334455",
      info = "#445566",
      warning = "#556677",
      danger = "#667788"
    )
  )

  theme <- bs_theme(
    4,
    primary = "#123",
    secondary = "#234",
    success = "#345",
    info = "#456",
    warning = "#567",
    danger = "#678"
  )
  expect_identical(
    bs_get_variables(theme, varnames),
    c(
      primary = "#112233",
      secondary = "#223344",
      success = "#334455",
      info = "#445566",
      warning = "#556677",
      danger = "#667788"
    )
  )
})`

const rtdal000328Source0004 = "test_that(\"bs3 accent colors\", {\n  varnames <- c(\n    \"primary\",\n    \"secondary\",\n    \"default\",\n    \"success\",\n    \"info\",\n    \"warning\",\n    \"danger\"\n  )\n  varnames <- paste0(\"brand-\", varnames)\n\n  # Baseline\n  theme <- bs_theme(\"3\")\n  expect_identical(\n    bs_get_variables(theme, varnames),\n    c(\n      `brand-primary` = \"#337ab7\",\n      `brand-secondary` = NA,\n      `brand-default` = NA,\n      `brand-success` = \"#5cb85c\",\n      `brand-info` = \"#5bc0de\",\n      `brand-warning` = \"#f0ad4e\",\n      `brand-danger` = \"#d9534f\"\n    )\n  )\n\n  expect_warning(\n    theme <- bs_theme(\n      \"3\",\n      primary = \"#123\",\n      secondary = \"#234\",\n      success = \"#345\",\n      info = \"#456\",\n      warning = \"#567\",\n      danger = \"#678\"\n    ),\n    \"doesn't support\"\n  )\n  expect_identical(\n    bs_get_variables(theme, varnames),\n    c(\n      `brand-primary` = \"#112233\",\n      `brand-secondary` = NA,\n      `brand-default` = NA,\n      `brand-success` = \"#334455\",\n      `brand-info` = \"#445566\",\n      `brand-warning` = \"#556677\",\n      `brand-danger` = \"#667788\"\n    )\n  )\n})"

const rtdal000328Source0005 = "test_that(\"bs_theme_fonts\", {\n  expected_result <- \"\\\"Source Sans Pro\\\", \\\"Open Sans\\\", Helvetica, sans-serif\"\n  candidates <- list(\n    # All separate\n    c(\"Source Sans Pro\", \"Open Sans\", \"Helvetica\", \"sans-serif\"),\n    # All together\n    c(\"'Source Sans Pro'\", \"Open Sans\", \"Helvetica, sans-serif\"),\n    # Mixed\n    c(\"'Source Sans Pro', \\\"Open Sans\\\", Helvetica, sans-serif\")\n  )\n\n  lapply(versions(), function(version) {\n    for (candidate in candidates) {\n      theme <- bs_theme(version, base_font = candidate)\n      expect_identical(\n        bs_get_variables(theme, \"font-family-base\"),\n        c(`font-family-base` = expected_result)\n      )\n    }\n    expect_error(bs_fonts(theme, \"\"))\n    expect_error(bs_fonts(theme, code = NA_character_))\n    expect_error(bs_fonts(theme, heading = TRUE))\n    expect_error(bs_fonts(theme, 10L))\n\n    # NOT an error\n    expect_error(bs_fonts(theme, NULL), NA)\n\n    theme <- bs_fonts(bs_theme(), base = \"a\", code = \"b\", heading = \"c\")\n    expect_identical(\n      bs_get_variables(\n        theme,\n        c(\"font-family-base\", \"font-family-monospace\", \"headings-font-family\")\n      ),\n      c(\n        `font-family-base` = \"a\",\n        `font-family-monospace` = \"b\",\n        `headings-font-family` = \"c\"\n      )\n    )\n  })\n})"

const rtdal000328Source0006 = "test_that(\"format_varnames\", {\n  expect_identical(format_varnames(\"a\"), \"`a`\")\n  expect_identical(format_varnames(c(\"a\", \"b\")), \"`a`, `b`\")\n  expect_identical(\n    format_varnames(c(\"foo bar\", \"baz qux\"), quot = \"'\", delim = \"/\"),\n    \"'foo bar'/'baz qux'\"\n  )\n})"

const rtdal000328Source0007 = `test_that("validate_and_normalize_colors", {
  expect_null(validate_and_normalize_colors(NULL))

  # Bad
  expect_error(
    validate_and_normalize_colors(list(mycolor = "")),
    "Invalid.*mycolor"
  )
  expect_error(validate_and_normalize_colors(list(foo = "bar")), "Invalid")
  expect_error(
    validate_and_normalize_colors(
      list(valid = "black", notvalid1 = "#00", notvalid2 = "#11111")
    ),
    "Invalid.*notvalid.*notvalid2"
  )
  expect_error(
    validate_and_normalize_colors(list(toomany = c("red", "blue"))),
    "Invalid.*toomany"
  )

  expect_identical(
    validate_and_normalize_colors(
      list(a = "#000", b = "white", c = "rgb(16, 32, 64)")
    ),
    list(a = "#000000", b = "#FFFFFF", c = "#102040")
  )
})`

const rtdal000328Source0008 = `test_that("bs_get_variables is fg/bg aware", {
  expect_equal(
    bs_get_variables(bs_theme(), c("bg", "fg")),
    c(bg = "#ffffff", fg = "#000")
  )
  expect_equal(
    bs_get_variables(bs_theme(version = 3), c("bg", "fg")),
    c(bg = "#fff", fg = "#000")
  )
  expect_equal(
    bs_get_variables(
      bs_theme(version = 4, bootswatch = "darkly"),
      c("bg", "fg")
    ),
    c(bg = "#222", fg = "#fff")
  )
  expect_equal(
    bs_get_variables(
      bs_theme(version = 3, bootswatch = "darkly"),
      c("bg", "fg")
    ),
    c(bg = "#222222", fg = "#fff")
  )
})`

const rtdal000328Source0009 = `test_that("theme-color('default') works as expected", {
  # default theme color derives defaults from $gray-300
  css <- sass::sass_partial(
    ".foo{color:theme-color('default')}",
    bs_theme(version = 4)
  )
  expect_css(css, ".foo{color:#dee2e6;}")
  # but can be customized via secondary
  css <- sass::sass_partial(
    ".foo{color:theme-color('default')}",
    bs_theme(version = 4, secondary = "red")
  )
  expect_css(css, ".foo{color:#FF0000;}")
  expect_error(
    sass::sass(
      list(bs_theme(), ".foo { @extend .bg-default; }")
    ),
    NA
  )
})`

const rtdal000328Source0010 = `test_that("bs_get_contrast() works as expected", {
  for (version in versions()) {
    base <- bs_theme(version)
    expect_equal(
      bs_get_contrast(base, "body-bg"),
      c("body-bg" = "#000000")
    )
    primary <- if ("3" %in% version) "brand-primary" else "primary"
    expect_equal(
      bs_get_contrast(base, c("body-bg", primary)),
      setNames(c("#000000", "#FFFFFF"), c("body-bg", primary))
    )
    inverted <- bs_theme_update(base, bg = "black", fg = "white")
    expect_equal(
      bs_get_contrast(inverted, "body-bg"),
      c("body-bg" = "#FFFFFF")
    )
    yb <- bs_theme(4, bg = "yellow", fg = "#0000FF")
    expect_equal(
      bs_get_contrast(yb, "input-bg"),
      c("input-bg" = "#0000FF")
    )
    yb <- bs_theme_update(
      yb,
      bg = "black",
      fg = "white",
      "color-contrast-light" = "#0000FF",
      "color-contrast-dark" = "yellow"
    )
    expect_equal(
      bs_get_contrast(yb, "input-bg"),
      c("input-bg" = "#FFFF00")
    )
    expect_error(
      bs_get_contrast(base, "font"),
      "Undefined variable"
    )
    expect_error(
      bs_get_contrast(base, "font-family-base"),
      "must be a color"
    )
    if ("3" %in% version) {
      next
    }
    light_success <- bs_theme_update(inverted, success = "#E5FFE5")
    expect_equal(
      bs_get_contrast(light_success, "success"),
      c("success" = "#000000")
    )
    expect_equal(
      bs_get_contrast(
        bs_theme_update(
          light_success,
          "color-contrast-light" = "#222",
          "min-contrast-ratio" = 1
        ),
        "success"
      ),
      c("success" = "#222222")
    )
    dark_success <- bs_theme_update(inverted, success = "#193319")
    expect_equal(
      bs_get_contrast(dark_success, "success"),
      c("success" = "#FFFFFF")
    )
    expect_equal(
      bs_get_contrast(
        bs_theme_update(dark_success, "color-contrast-light" = "#F8F9FA"),
        "success"
      ),
      c("success" = "#F8F9FA")
    )
  }
})`

