const rtdal000333Source0028 = `test_that("update_toolbar_input_select() keeps current value when choices change", {
  # Mock session with a current input value
  session <- list(
    sendInputMessage = function(id, message) {
      # Capture the message to verify behavior
      session$last_message <<- message
    },
    input = list(test_select = "B")
  )

  # Update choices - current value "B" is still valid, should be kept
  update_toolbar_input_select(
    "test_select",
    choices = c("A", "B", "C"),
    session = session
  )
  expect_null(session$last_message$value)

  # Update choices - current value "B" is no longer valid, should keep current (don't update)
  session$input$test_select <- "B"
  update_toolbar_input_select(
    "test_select",
    choices = c("X", "Y", "Z"),
    session = session
  )
  expect_null(session$last_message$value)
})`

const rtdal000333Source0029 = "test_that(\"process_choices_selected() handles all cases correctly\", {\n  # Case 1: Valid selected value with choices\n  result <- process_choices_selected(c(\"A\", \"B\", \"C\"), \"B\", \"test_id\")\n  expect_equal(result$value, \"B\")\n  expect_null(result$error)\n\n  # Case 2: Invalid selected value with choices\n  result <- process_choices_selected(c(\"A\", \"B\", \"C\"), \"D\", \"test_id\")\n  expect_null(result$value)\n  expect_match(result$error, \"not in `choices`\")\n\n  # Case 3: selected is a vector (invalid)\n  result <- process_choices_selected(c(\"A\", \"B\", \"C\"), c(\"A\", \"B\"), \"test_id\")\n  expect_null(result$value)\n  expect_match(result$error, \"single value\")\n\n  # Case 4: No selected, no choices\n  result <- process_choices_selected(NULL, NULL, \"test_id\")\n  expect_null(result$value)\n  expect_null(result$error)\n\n  # Case 5: No selected, has choices - selects first choice (use_first_choice = TRUE)\n  result <- process_choices_selected(\n    c(\"A\", \"B\", \"C\"),\n    NULL,\n    \"test_id\",\n    use_first_choice = TRUE\n  )\n  expect_equal(result$value, \"A\")\n  expect_null(result$error)\n\n  # Case 5b: No selected, has choices - keeps NULL (use_first_choice = FALSE, for updates)\n  result <- process_choices_selected(\n    c(\"A\", \"B\", \"C\"),\n    NULL,\n    \"test_id\",\n    use_first_choice = FALSE\n  )\n  expect_null(result$value)\n  expect_null(result$error)\n\n  # Case 6: Valid selected with named choices\n  result <- process_choices_selected(\n    c(\"Label A\" = \"val_a\", \"Label B\" = \"val_b\"),\n    \"val_a\",\n    \"test_id\"\n  )\n  expect_equal(result$value, \"val_a\")\n  expect_null(result$error)\n\n  # Case 7: Invalid selected (using label instead of value)\n  result <- process_choices_selected(\n    c(\"Label A\" = \"val_a\", \"Label B\" = \"val_b\"),\n    \"Label A\",\n    \"test_id\"\n  )\n  expect_null(result$value)\n  expect_match(result$error, \"not in `choices`\")\n\n  # Case 8: Valid selected with grouped choices\n  result <- process_choices_selected(\n    list(\"Group 1\" = c(\"A\", \"B\"), \"Group 2\" = c(\"C\", \"D\")),\n    \"B\",\n    \"test_id\"\n  )\n  expect_equal(result$value, \"B\")\n  expect_null(result$error)\n\n  # Case 9: Invalid selected with grouped choices\n  result <- process_choices_selected(\n    list(\"Group 1\" = c(\"A\", \"B\"), \"Group 2\" = c(\"C\", \"D\")),\n    \"E\",\n    \"test_id\"\n  )\n  expect_null(result$value)\n  expect_match(result$error, \"not in `choices`\")\n\n  # Case 10: Selected without choices (invalid)\n  result <- process_choices_selected(NULL, \"B\", \"test_id\")\n  expect_null(result$value)\n  expect_match(result$error, \"cannot be set without `choices`\")\n})"

const rtdal000333Source0030 = `test_that("update_toolbar_input_button() warns for blank label", {
  # Note: We can't fully test these functions without a Shiny session,
  # but we can test that the warning is issued before the session error occurs.

  # Empty string label should warn
  expect_warning(
    expect_error(
      update_toolbar_input_button(
        "test_id",
        label = ""
      )
    ),
    "non-empty string label"
  )

  # Whitespace-only label should warn
  expect_warning(
    expect_error(
      update_toolbar_input_button(
        "test_id",
        label = "   "
      )
    ),
    "non-empty string label"
  )

  # Empty tag label should warn
  expect_warning(
    expect_error(
      update_toolbar_input_button(
        "test_id",
        label = span("")
      )
    ),
    "non-empty string label"
  )
})`

const rtdal000333Source0031 = `test_that("update_toolbar_input_button() can disable and reenable button", {
  # Mock session that captures sendInputMessage calls
  session <- list(
    sendInputMessage = function(id, message) {
      session$last_id <<- id
      session$last_message <<- message
    }
  )

  # Test disabling a button
  update_toolbar_input_button(
    "test_btn",
    label = "Test Button",
    disabled = TRUE,
    session = session
  )

  expect_equal(session$last_id, "test_btn")
  expect_equal(session$last_message$disabled, TRUE)

  # Test re-enabling a button
  update_toolbar_input_button(
    "test_btn",
    label = "Test Button",
    disabled = FALSE,
    session = session
  )

  expect_equal(session$last_id, "test_btn")
  expect_equal(session$last_message$disabled, FALSE)

  # Test updating multiple properties including disabled state
  update_toolbar_input_button(
    "test_btn",
    label = "Updated",
    icon = shiny::icon("check"),
    disabled = TRUE,
    session = session
  )

  expect_equal(session$last_id, "test_btn")
  expect_equal(session$last_message$disabled, TRUE)
  expect_true(!is.null(session$last_message$label))
  expect_true(!is.null(session$last_message$icon))
})`

