const rtdal000342Source0006 = `download_and_copy_fonts <- function(theme, rule_file = "_bootswatch.scss") {
  theme_file <- file.path(theme, rule_file)

  if (!file.exists(theme_file)) {
    stop("Couldn't find '", rule_file, "' in ", theme)
  }

  theme_scss <- readLines(theme_file)

  web_font_path <- grep(
    "$web-font-path:",
    theme_scss,
    value = TRUE,
    fixed = TRUE
  )
  if (!length(web_font_path)) {
    return()
  }
  web_font_url <- strsplit(trimws(web_font_path), "\\s+")[[1]][2]
  if (!length(web_font_url)) {
    warning(
      "Wasn't able to extract a url for $web-font-path from theme: ",
      theme
    )
    return()
  }
  web_font_url <- gsub('(^")|("$)', '', web_font_url)
  css_file <- file.path(theme, "font.css")
  download.file(
    utils::URLencode(web_font_url),
    css_file,
    method = "libcurl",
    headers = request_headers
  )
  css <- readLines(css_file)
  urls <- sass:::extract_group(css, "url\\(([^)]+)")
  basenames <- basename(urls)
  n_fonts <- length(urls)
  for (i in seq_along(urls)) {
    url <- urls[[i]]
    nm <- basenames[[i]]

    if (!grepl("[.]woff2$", nm)) {
      stop("Expected a woff2 font file")
    }

    target <- file.path(fonts_home, nm)
    # The basename can sometimes be very long, and R CMD check
    # will complain if the target file is over 100 characters long,
    # so shorten it if necessary
    if (nchar(file.path("bslib", target)) > 100) {
      nm <- paste0(
        rlang::hash(tools::file_path_sans_ext(nm)),
        ".",
        tools::file_ext(nm)
      )
      target <- file.path(fonts_home, nm)
    }

    cat(sprintf("\r  Downloading font file %d of %d", i, n_fonts))
    tryCatch(
      download.file(
        url,
        target,
        method = "libcurl",
        headers = request_headers,
        quiet = TRUE
      ),
      error = function(e) {
        cat("\n")
        warning("Failed to download: ", url, call. = FALSE)
      }
    )
    css <- sub(url, file.path("fonts", nm), css, fixed = TRUE)
  }
  cat("\n")
  writeLines(css, css_file)
  NULL
}`

