  expect_true(validate_key("_"))

  expect_error(validate_key("a.b"))
  expect_error(validate_key("a,b"))
  expect_error(validate_key("é"))
  expect_error(validate_key("ABC"))
  expect_error(validate_key("_A"))
  expect_error(validate_key("!"))
  expect_error(validate_key("a b"))
