const rtdal000366Source0001 = "common_hook <- function() {\n  substitute(\n    {\n      # This should not happen in a new R session, but just to be safe\n      while (\"tools:callr\" %in% search()) {\n        detach(\"tools:callr\")\n      }\n      env <- readRDS(`__envfile__`)\n\n      # OpenTelemetry setup\n      has_otel <- nzchar(Sys.getenv(\"TRACEPARENT\")) &&\n        requireNamespace(\"otel\", quietly = TRUE)\n      assign(envir = env$`__callr_data__`, \"has_otel\", has_otel)\n      if (has_otel) {\n        hdrs <- as.list(c(\n          traceparent = Sys.getenv(\"TRACEPARENT\"),\n          tracestate = Sys.getenv(\"TRACESTATE\"),\n          baggage = Sys.getenv(\"BAGGAGE\")\n        ))\n        prtctx <- otel::extract_http_context(hdrs)\n        assign(\n          envir = env$`__callr_data__`,\n          \"otel_span\",\n          otel::start_local_active_span(\n            \"callr subprocess\",\n            options = list(parent = prtctx),\n            activation_scope = .GlobalEnv,\n            end_on_exit = TRUE\n          )\n        )\n      }\n\n      do.call(\"attach\", list(env, pos = length(search()), name = \"tools:callr\"))\n      data <- env$`__callr_data__`\n      data$pxlib <- data$load_client_lib(\n        data$sofile[[paste0(\"arch-\", .Platform$r_arch)]],\n        data$pxdir\n      )\n      options(error = function() invokeRestart(\"abort\"))\n      rm(list = c(\"data\", \"env\", \"has_otel\"))\n\n      lapply(\n        c(\n          \"R_ENVIRON\",\n          \"R_ENVIRON_USER\",\n          \"R_PROFILE\",\n          \"R_PROFILE_USER\",\n          \"R_LIBS\",\n          \"R_LIBS_USER\",\n          \"R_LIBS_SITE\"\n        ),\n        function(var) {\n          bakvar <- paste0(\"CALLR_\", var, \"_BAK\")\n          val <- Sys.getenv(bakvar, NA_character_)\n          if (!is.na(val)) {\n            do.call(\"Sys.setenv\", structure(list(val), names = var))\n          } else {\n            Sys.unsetenv(var)\n          }\n          Sys.unsetenv(bakvar)\n        }\n      )\n\n      Sys.unsetenv(\"CALLR_CHILD_R_LIBS\")\n      Sys.unsetenv(\"CALLR_CHILD_R_LIBS_SITE\")\n      Sys.unsetenv(\"CALLR_CHILD_R_LIBS_USER\")\n    },\n    list(\"__envfile__\" = env_file)\n  )\n}"

const rtdal000366Source0002 = `default_load_hook <- function(user_hook = NULL) {
  prepare_client_files()
  hook <- common_hook()

  if (!is.null(user_hook)) {
    hook <- substitute(
      {
        d
        u
      },
      list(d = hook, u = user_hook)
    )
  }
  paste0(deparse(hook), "\n")
}`

const rtdal000366Source0003 = "session_load_hook <- function(user_hook = NULL) {\n  chook <- common_hook()\n  ehook <- substitute({\n    data <- as.environment(\"tools:callr\")$`__callr_data__`\n    data$pxlib$disable_fd_inheritance()\n    rm(data)\n  })\n\n  hook <- substitute(\n    {\n      c\n      e\n    },\n    list(c = chook, e = ehook)\n  )\n\n  if (!is.null(user_hook)) {\n    hook <- substitute(\n      {\n        d\n        u\n      },\n      list(d = hook, u = user_hook)\n    )\n  }\n\n  hook <- substitute(\n    {\n      err_ <- TRUE\n      callr_startup_hook <- function() {\n        on.exit(if (err_) quit(\"no\", 1, TRUE))\n        {\n          `_hook_`\n        }\n        err_ <<- FALSE\n      }\n      callr_startup_hook()\n      rm(err_, callr_startup_hook)\n    },\n    list(\"_hook_\" = hook)\n  )\n\n  paste0(deparse(hook), \"\\n\")\n}"

const rtdal000366Source0005 = "add_hook <- function(...) {\n  args <- list(...)\n  if (length(args) != 1L) {\n    stop(\"More than one argument passed to `add_hook`\")\n  }\n\n  name <- names(args)\n  if (is.null(name)) {\n    stop(\"Argument passed to `add_hook` must be named\")\n  }\n\n  hook <- args[[1]]\n  if (is.null(hook)) {\n    rm(list = name, envir = user_hooks_env)\n  } else {\n    assign(name, match.fun(hook), envir = user_hooks_env)\n  }\n\n  invisible()\n}"

