const rtdal000368Source0007 = `update_options <- function(old_opts, ...) {
  new_opts <- list(...)
  stopifnot(is.named(new_opts))
  check_for_option_names(old_opts, new_opts)
  utils::modifyList(old_opts, new_opts)
}`

const rtdal000368Source0008 = `check_for_option_names <- function(old, new) {
  if (length(miss <- setdiff(names(new), names(old)))) {
    throw(new_error(
      "Unknown option",
      if (length(miss) > 1) "s",
      ":",
      enumerate(sQuote(miss))
    ))
  }
}`

