const rtdal000372Source0001 = "r_process <- suppressMessages(R6::R6Class(\n  \"r_process\",\n  inherit = processx::process,\n  public = list(\n    #' @description\n    #' Start a new R process in the background.\n    #' @param options A list of options created via [r_process_options()].\n    #' @return A new `r_process` object.\n    initialize = function(options) rp_init(self, private, super, options),\n\n    #' @description\n    #' Return the result, an R object, from a finished\n    #' background R process. If the process has not finished yet, it throws\n    #' an error. (You can use `wait()` method (see [processx::process]) to\n    #' wait for the process to finish, optionally with a timeout.) You can\n    #' also use [processx::poll()] to wait for the end of the process,\n    #' together with other processes or events.\n    #'\n    #' @return The return value of the R expression evaluated in the R\n    #' process.\n    get_result = function() rp_get_result(self, private),\n\n    #' @description\n    #' Delete the temporary files created for this R process.\n    #' Only call this if you are sure that the process is done and you\n    #' don't need the result anymore. If you don't call this method\n    #' explicitly, the temporary files will be deleted when the process\n    #' object is garbage collected.\n    cleanup = function() {\n      unlink(private$options$tmp_files, recursive = TRUE)\n    },\n\n    #' @description\n    #' Clean up temporary files once an R process has finished and its\n    #' handle is garbage collected.\n    finalize = function() {\n      self$cleanup()\n      if (\"finalize\" %in% ls(super)) super$finalize()\n    }\n  ),\n  private = list(\n    options = NULL\n  )\n))"

const rtdal000372Source0002 = `rp_init <- function(self, private, super, options) {
  ## This contains the context that we set up in steps
  options <- convert_and_check_my_args(options)

  options <- setup_script_files(options)
  options <- setup_context(options)
  options <- setup_r_binary_and_args(options)

  otel_span <- otel::start_span(
    "callr::r_process",
    attributes = otel::as_attributes(options)
  )
  otel::local_active_span(otel_span)
  otel::log_debug("start r_process")
  if (otel::is_tracing_enabled()) {
    hdrs <- otel::pack_http_context()
    names(hdrs) <- toupper(names(hdrs))
    options$env[names(hdrs)] <- hdrs
  }
  options$otel_span <- otel_span

  private$options <- options

  with_envvar(
    options$env,
    do.call(
      super$initialize,
      c(
        list(
          options$bin,
          options$real_cmdargs,
          stdout = options$stdout,
          stderr = options$stderr,
          poll_connection = options$poll_connection,
          supervise = options$supervise
        ),
        options$extra
      )
    )
  )

  invisible(self)
}`

const rtdal000372Source0003 = `rp_get_result <- function(self, private) {
  if (self$is_alive()) {
    private$options$otel_span$add_event(
      "get_result",
      attributes = list(done = FALSE)
    )
    throw(new_error("Still alive"))
  }
  on.exit(private$options$otel_span$end(status_code = "auto"), add = TRUE)

  ## This is artificial...
  out <- list(
    status = self$get_exit_status(),
    stdout = "",
    stderr = "",
    timeout = FALSE
  )

  get_result(out, private$options)
}`

