const rtdal000373Source0001 = "r_session <- suppressMessages(R6::R6Class(\n  \"r_session\",\n  inherit = processx::process,\n  public = list(\n    #' @field status\n    #' Status codes returned by `read()`.\n    status = list(\n      DONE = 200L,\n      STARTED = 201L,\n      ATTACH_DONE = 202L,\n      MSG = 301L,\n      EXITED = 500L,\n      CRASHED = 501L,\n      CLOSED = 502L\n    ),\n\n    #' @description\n    #' creates a new R background process. It can wait for the process to\n    #' start up (`wait = TRUE`), or return immediately, i.e. before\n    #' the process is actually ready to run. In the latter case you may call\n    #' the `poll_process()` method to make sure it is ready.\n    #'\n    #' @param options A list of options created via [r_session_options()].\n    #' @param wait Whether to wait for the R process to start and be ready\n    #'   for running commands.\n    #' @param wait_timeout Timeout for waiting for the R process to start,\n    #'   in milliseconds.\n    #' @return An `r_session` object.\n    initialize = function(\n      options = r_session_options(),\n      wait = TRUE,\n      wait_timeout = 3000\n    ) {\n      rs_init(self, private, super, options, wait, wait_timeout)\n    },\n\n    #' @description\n    #' Similar to [r()], but runs the function in a permanent background\n    #' R session. It throws an error if the function call generated an\n    #' error in the child process.\n    #' @return The return value of the R expression.\n    run = function(func, args = list(), package = NULL) {\n      rs_run(self, private, func, args, package)\n    },\n\n    #' @description\n    #' Similar to `$run()`, but returns the standard output and error of\n    #' the child process as well. It does not throw on errors, but\n    #' returns a non-`NULL` `error` member in the result list.\n    #'\n    #' @return A list with the following entries.\n    #' * `result`: The value returned by `func`. On error this is `NULL`.\n    #' * `stdout`: The standard output of the process while evaluating\n    #    the `func` call,\n    #' * `stderr`: The standard error of the process while evaluating\n    #'   the `func` call.\n    #' * `error`: On error it contains an error object, that contains the\n    #'   error thrown in the subprocess. Otherwise it is `NULL`.\n    #' * `code`, `message`: These fields are used by call internally and\n    #'   you can ignore them.\n    run_with_output = function(func, args = list(), package = NULL) {\n      rs_run_with_output(self, private, func, args, package)\n    },\n\n    #' @description\n    #' Starts running a function in the background R session, and\n    #' returns immediately. To check if the function is done, call the\n    #' `poll_process()` method.\n    call = function(func, args = list(), package = NULL) {\n      rs_call(self, private, func, args, package)\n    },\n\n    #' @description\n    #' Poll the R session with a timeout. If the session has finished the\n    #' computation, it returns with `\"ready\"`. If the timeout\n    #' is reached, it returns with `\"timeout\"`.\n    #'\n    #' @param timeout Timeout period in milliseconds.\n    #' @return Character string `\"ready\"` or `\"timeout\"`.\n    poll_process = function(timeout) rs_poll_process(self, private, timeout),\n\n    #' @description\n    #' Return the state of the R session.\n    #'\n    #' @return Possible values:\n    #'   * `\"starting\"`: starting up,\n    #'   * `\"idle\"`: ready to compute,\n    #'   * `\"busy\"`: computing right now,\n    #'   * `\"finished\"`: the R process has finished.\n    get_state = function() rs_get_state(self, private),\n\n    #' @description\n    #' Returns the elapsed time since the R process has started, and the\n    #' elapsed time since the current computation has started. The latter\n    #' is `NA` if there is no active computation.\n    #' @return Named vector of `POSIXct` objects. The names are `\"total\"`\n    #'   and `\"current\"`.\n    get_running_time = function() rs_get_running_time(self, private),\n\n    #' @description\n    #' Reads an event from the child process, if there is one available.\n    #' Events might signal that the function call has finished, or they\n    #' can be progress report events.\n    #'\n    #' This is a low level function that you only need to use if you\n    #' want to process events (messages) from the R session manually.\n    #'\n    #' @return `NULL` if no events are available. Otherwise a named list,\n    #'   which is also a `callr_session_result` object. The list always has\n    #'   a `code` entry which is the type of the event. See also\n    #'   `r_session$public_fields$status` for symbolic names of the\n    #'   event types.\n    #'   * `200`: (`DONE`) The computation is done, and the event includes\n    #'      the result, in the same form as for the `run()` method.\n    #'   * `201`: (`STARTED`) An R session that was in 'starting' state is\n    #'      ready to go.\n    #'   * `202`: (`ATTACH_DONE`) Used by the `attach()` method.\n    #'   * `301`: (`MSG`) A message from the subprocess. The message is a\n    #'      condition object with class `callr_message`. (It typically has\n    #'      other classes, e.g. `cli_message` for output from the cli\n    #'      package.)\n    #'   * `500`: (`EXITED`) The R session finished cleanly. This means\n    #'      that the evaluated expression quit R.\n    #'   * `501`: (`CRASHED`) The R session crashed or was killed.\n    #'   * `502`: (`CLOSED`) The R session closed its end of the connection\n    #'      that callr uses for communication.\n\n    read = function() rs_read(self, private),\n\n    #' @description\n    #' Terminate the current computation and the R process.\n    #' The session object will be in `\"finished\"` state after this.\n    #' @param grace Grace period in milliseconds, to wait for the\n    #' subprocess to exit cleanly, after its standard input is closed.\n    #' If the process is still running after this period, it will be\n    #' killed.\n    close = function(grace = 1000) rs_close(self, private, grace),\n\n    #' @description\n    #' The `traceback()` method can be used after an error in the R\n    #' subprocess. It is equivalent to the [base::traceback()] call, in\n    #' the subprocess.\n    #'\n    #' On callr version 3.8.0 and above, you need to set the\n    #' `callr.traceback` option to `TRUE` (in the main process) to make\n    #' the subprocess save the trace on error. This is because saving\n    #' the trace can be costly for large objects passed as arguments.\n    #' @return The same output as from [base::traceback()]\n    traceback = function() rs_traceback(self, private),\n\n    #' @description\n    #' Interactive debugger to inspect the dumped frames in the subprocess,\n    #' after an error. See more at [r_session_debug].\n    #'\n    #' On callr version 3.8.0 and above, you need to set the\n    #' `callr.traceback` option to `TRUE` (in the main process) to make\n    #' the subprocess dump frames on error. This is because saving\n    #' the frames can be costly for large objects passed as arguments.\n    debug = function() rs_debug(self, private),\n\n    #' @description Experimental function that provides a REPL\n    #' (Read-Eval-Print-Loop) to the subprocess.\n    attach = function() rs_attach(self, private),\n\n    #' @description\n    #' Print method for an `r_session`.\n    #' @param ... Arguments are not used currently.\n    print = function(...) {\n      cat(\n        sep = \"\",\n        \"R SESSION, \",\n        if (self$is_alive()) {\n          paste0(\"alive, \", self$get_state(), \", \")\n        } else {\n          \"finished, \"\n        },\n        \"pid \",\n        self$get_pid(),\n        \".\\n\"\n      )\n      invisible(self)\n    },\n\n    #' @description\n    #' Delete the temporary files created for this R session. Only call\n    #' this if you are sure that the process is done and you don't need to\n    #' read from it anymore. If you don't call this method explicitly, the\n    #' temporary files will be deleted when the process object is garbage\n    #' collected.\n    cleanup = function() {\n      unlink(private$tmp_output_file)\n      unlink(private$tmp_error_file)\n      unlink(private$options$tmp_files, recursive = TRUE)\n    },\n\n    #' @description\n    #' Finalizer that is called when garbage collecting an `r_session`\n    #' object, to clean up temporary files.\n    finalize = function() {\n      private$options$otel_span$add_event(\"finalizer\")\n      private$options$otel_span$end()\n      self$cleanup()\n      if (\"finalize\" %in% ls(super)) super$finalize()\n    }\n  ),\n\n  private = list(\n    options = NULL,\n    state = NULL,\n    started_at = NULL,\n    fun_started_at = as.POSIXct(NA),\n    pipe = NULL,\n\n    tmp_output_file = NULL,\n    tmp_error_file = NULL,\n\n    func_file = NULL,\n    res_file = NULL,\n\n    buffer = NULL,\n    read_buffer = function() rs__read_buffer(self, private),\n    read_message = function() rs__read_message(self, private),\n\n    get_result_and_output = function(std = FALSE) {\n      rs__get_result_and_output(self, private, std)\n    },\n    report_back = function(code, text = \"\") {\n      rs__report_back(self, private, code, text)\n    },\n    write_for_sure = function(text) rs__write_for_sure(self, private, text),\n    parse_msg = function(msg) rs__parse_msg(self, private, msg),\n    attach_wait = function() rs__attach_wait(self, private)\n  )\n))"

const rtdal000373Source0002 = `rs_init <- function(self, private, super, options, wait, wait_timeout) {
  options$func <- options$func %||%
    function() {}
  options$args <- list()
  options$load_hook <- session_load_hook(options$load_hook)

  options <- convert_and_check_my_args(options)
  options <- setup_context(options)
  options <- setup_r_binary_and_args(options, script_file = FALSE)

  otel_span <- otel::start_span(
    "callr::r_session",
    attributes = otel::as_attributes(options)
  )
  otel::local_active_span(otel_span)
  if (otel::is_tracing_enabled()) {
    hdrs <- otel::pack_http_context()
    names(hdrs) <- toupper(names(hdrs))
    options$env[names(hdrs)] <- hdrs
  }
  otel::log_debug("callr::r_session start")
  options$otel_span <- otel_span

  private$options <- options

  prepare_client_files()
  with_envvar(
    options$env,
    do.call(
      super$initialize,
      c(
        list(
          options$bin,
          options$real_cmdargs,
          stdin = "|",
          stdout = "|",
          stderr = "|",
          poll_connection = TRUE
        ),
        options$extra
      )
    )
  )

  ## Make child report back when ready
  private$report_back(201, "ready to go")

  private$pipe <- self$get_poll_connection()

  private$started_at <- Sys.time()
  private$state <- "starting"

  if (wait) {
    otel::start_local_active_span("r_session$initialize() wait")
    timeout <- wait_timeout
    have_until <- Sys.time() + as.difftime(timeout / 1000, units = "secs")
    pr <- self$poll_io(timeout)
    out <- ""
    err <- ""
    while (any(pr == "ready")) {
      if (pr["output"] == "ready") {
        out <- paste0(out, self$read_output())
      }
      if (pr["error"] == "ready") {
        err <- paste0(err, self$read_error())
      }
      if (pr["process"] == "ready") {
        break
      }
      timeout <- as.double(have_until - Sys.time(), units = "secs") * 1000
      pr <- self$poll_io(as.integer(timeout))
    }

    if (pr["process"] == "ready") {
      msg <- self$read()
      out <- paste0(out, msg$stdout)
      err <- paste0(err, msg$stderr)
      if (msg$code != 201) {
        data <- list(
          status = self$get_exit_status(),
          stdout = out,
          stderr = err,
          timeout = FALSE
        )
        throw(new_callr_crash_error(data, "Failed to start R session"))
      }
    } else if (pr["process"] != "ready") {
      cat("stdout:]\n", out, "\n")
      cat("stderr:]\n", err, "\n")
      throw(new_error("Could not start R session, timed out"))
    }
  }

  invisible(self)
}`

const rtdal000373Source0003 = `rs_read <- function(self, private) {
  otel::local_active_span(private$options$otel_span)
  spn <- otel::start_local_active_span("r_session$read")
  if (!is.null(private$buffer)) {
    # There is a partial message in the buffer, try to finish it.
    out <- private$read_buffer()
  } else {
    # A new message.
    out <- private$read_message()
  }
  if (!length(out)) {
    if (processx::processx_conn_is_incomplete(private$pipe)) {
      spn$set_attribute("message", FALSE)
      return()
    }
    if (self$is_alive()) {
      # We do this in on.exit(), because parse_msg still reads the streams
      on.exit(self$kill(), add = TRUE)
      out <- list(
        header = list(
          code = 502,
          length = 0,
          rest = "R session closed the process connection, killed"
        )
      )
    } else if (identical(es <- self$get_exit_status(), 0L)) {
      out <- list(
        header = list(
          code = 500,
          length = 0,
          rest = "R session finished cleanly"
        )
      )
    } else {
      out <- list(
        header = list(
          code = 501,
          length = 0,
          rest = paste0("R session crashed with exit code ", es)
        )
      )
    }
  }
  if (length(out)) {
    spn$set_attribute("message", TRUE)
    if (!is.null(out$header$code)) {
      spn$set_attribute("status_code", out$header$code)
    }
    private$parse_msg(out)
  } else {
    spn$set_attribute("message", FALSE)
  }
}`

const rtdal000373Source0004 = `rs__read_buffer <- function(self, private) {
  # There is a partial message in the buffer already, we need to
  # read some more
  need <- private$buffer$header$length - private$buffer$got
  chunk <- processx::processx_conn_read_chars(private$pipe, need)
  got <- nchar(chunk)
  if (got == 0) {
    # make this special case fast
    NULL
  } else if (got == need) {
    msg <- list(
      header = private$buffer$header,
      body = paste(c(private$buffer$chunks, list(chunk)), collapse = "")
    )
    private$buffer <- NULL
    msg
  } else {
    private$buffer$got <- private$buffer$got + got
    private$buffer$chunks <- c(private$buffer$chunks, list(chunk))
    NULL
  }
}`

const rtdal000373Source0005 = `rs__read_message <- function(self, private) {
  # A new message, we can surely read the first line
  out <- processx::processx_conn_read_lines(private$pipe, 1)
  if (length(out) == 0) {
    return(NULL)
  }

  header <- rs__parse_header(out)
  body <- ""
  if (header$length > 0) {
    body <- processx::processx_conn_read_chars(
      private$pipe,
      header$length
    )
  }
  got <- nchar(body)
  if (got < header$length) {
    # Partial message
    private$buffer <- list(
      header = header,
      got = got,
      chunks = list(body)
    )
    NULL
  } else {
    list(header = header, body = body)
  }
}`

const rtdal000373Source0007 = `rs_close <- function(self, private, grace) {
  otel::local_active_span(private$options$otel_span)
  otel::start_local_active_span("r_session$close")
  processx::processx_conn_close(self$get_input_connection())
  self$poll_process(grace)
  self$kill()
  self$wait(1000)
  if (self$is_alive()) {
    throw(new_error("Could not kill background R session"))
  }
  private$state <- "finished"
  private$fun_started_at <- as.POSIXct(NA)
  processx::processx_conn_close(private$pipe)
  processx::processx_conn_close(self$get_output_connection())
  processx::processx_conn_close(self$get_error_connection())
  private$options$otel_span$end()
  invisible()
}`

const rtdal000373Source0008 = `rs_call <- function(self, private, func, args, package) {
  otel::local_active_span(private$options$otel_span)
  otel::start_local_active_span("r_session$call")
  ## We only allow a new command if the R session is idle.
  ## This allows keeping a clean state
  ## TODO: do we need a state at all?
  if (private$state == "starting") {
    throw(new_error("R session not ready yet"))
  }
  if (private$state == "finished") {
    throw(new_error("R session finished"))
  }
  if (private$state == "busy") {
    throw(new_error("R session busy"))
  }

  ## Save the function in a file
  private$options$func <- func
  private$options$args <- args
  private$options$package <- package
  private$options$func_file <- save_function_to_temp(private$options)
  private$options$result_file <- callr_tempfile("callr-rs-result-")
  private$options$tmp_files <-
    c(
      private$options$tmp_files,
      private$options$func_file,
      private$options$result_file
    )

  ## Maybe we need to redirect stdout / stderr
  re_stdout <- if (is.null(private$options$stdout)) {
    private$tmp_output_file <- callr_tempfile("callr-rs-stdout-")
  }
  re_stderr <- if (is.null(private$options$stderr)) {
    private$tmp_error_file <- callr_tempfile("callr-rs-stderr-")
  }

  pre <- rs__prehook(re_stdout, re_stderr)
  post <- rs__posthook(re_stdout, re_stderr)

  ## Run an expr that loads it, in the child process, with error handlers
  expr <- make_vanilla_script_expr(
    private$options$func_file,
    private$options$result_file,
    private$options$error,
    pre_hook = pre,
    post_hook = post,
    messages = TRUE,
    print_error = FALSE,
    exit_on_error = FALSE
  )
  cmd <- paste0(deparse(expr), "\n")

  ## Write this to stdin
  private$write_for_sure(cmd)
  private$fun_started_at <- Sys.time()

  ## Report back when done
  report_str <- paste0("done ", basename(private$options$result_file))
  private$report_back(200, report_str)

  private$state <- "busy"
}`

const rtdal000373Source0009 = `rs_run_with_output <- function(self, private, func, args, package) {
  self$call(func, args, package)

  go <- TRUE
  res <- NULL

  while (go) {
    ## TODO: why is this in a tryCatch?
    res <- tryCatch(
      {
        processx::poll(list(private$pipe), -1)
        msg <- self$read()
        if (is.null(msg)) {
          next
        }
        if (msg$code == 200 || (msg$code >= 500 && msg$code < 600)) {
          return(msg)
        }
        if (msg$code == 301) {
          rs__handle_condition(msg$message)
        }
      },
      interrupt = function(e) {
        self$interrupt()
        ## The R process will catch the interrupt, and then save the
        ## error object to a file, but this might still take some time,
        ## so we need to poll here. If the bg process ignores
        ## interrupts, then we kill it.
        ps <- processx::poll(list(private$pipe), 1000)[[1]]
        if (ps == "timeout") {
          self$kill()
        } else {
          res <<- self$read()
          go <<- FALSE
        }
        iconn <- structure(
          list(message = "Interrupted"),
          class = c("interrupt", "condition")
        )
        signalCondition(iconn)
        cat("\n")
        invokeRestart("abort")
      }
    )
  }
  res
}`

const rtdal000373Source0010 = `rs_run <- function(self, private, func, args, package) {
  res <- rs_run_with_output(self, private, func, args, package)
  if (is.null(res$error)) {
    res$result
  } else {
    res$stdout <- paste0(res$stdout, self$read_output())
    res$stderr <- paste0(res$stderr, self$read_error())
    throw(res$error)
  }
}`

const rtdal000373Source0012 = `rs_get_running_time <- function(self, private) {
  now <- Sys.time()
  finished <- private$state == "finished"
  idle <- private$state == "idle"
  missing <- as.difftime(NA_real_, units = "secs")
  c(
    total = now - private$started_at,
    current = if (finished | idle) missing else now - private$fun_started_at
  )
}`

const rtdal000373Source0013 = `rs_poll_process <- function(self, private, timeout) {
  processx::poll(list(self$get_poll_connection()), timeout)[[1]]
}`

const rtdal000373Source0014 = "rs_traceback <- function(self, private) {\n  tb <- self$run(function() {\n    traceback(as.environment(\"tools:callr\")$`__callr_data__`$.Traceback, 10)\n  })\n  if (is.null(tb)) {\n    throw(new_error(\"No traceback was recorded in the subprocess (yet?)\"))\n  } else {\n    traceback(utils::head(tb, -12))\n  }\n}"

const rtdal000373Source0015 = "rs_debug <- function(self, private) {\n  hasdump <- self$run(function() {\n    !is.null(as.environment(\"tools:callr\")$`__callr_data__`$.Last.dump)\n  })\n  if (!hasdump) {\n    stop(\"Can't find dumped frames, nothing to debug\")\n  }\n\n  help <- function() {\n    cat(\n      \"Debugging in process \",\n      self$get_pid(),\n      \", press CTRL+C (ESC) or type .q to quit. Commands:\\n\",\n      sep = \"\"\n    )\n    cat(\n      \"  .where       -- print stack trace\\n\",\n      \"  .inspect <n> -- inspect a frame, 0 resets to .GlobalEnv\\n\",\n      \"  .help        -- print this message\\n\",\n      \"  .q           -- quit debugger\\n\",\n      \"  <cmd>        -- run <cmd> in frame or .GlobalEnv\\n\\n\",\n      sep = \"\"\n    )\n  }\n\n  should_quit <- FALSE\n  translate_cmd <- function(cmd) {\n    if (cmd == \".where\") {\n      traceback(tb)\n      if (frame) {\n        cat(\"Inspecting frame\", frame, \"\\n\")\n      }\n      NULL\n    } else if (cmd == \".help\") {\n      help()\n      NULL\n    } else if (grepl(\"^.inspect \", cmd)) {\n      newframe <- as.integer(strsplit(cmd, \" \")[[1]][[2]])\n      if (is.na(newframe)) {\n        message(\"Cannot parse frame number\")\n      } else {\n        frame <<- newframe\n      }\n      NULL\n    } else if (cmd == \".q\") {\n      should_quit <<- TRUE\n      NULL\n    } else {\n      cmd\n    }\n  }\n\n  help()\n  tb <- self$traceback()\n  frame <- 0L\n\n  while (TRUE) {\n    cat(\"\\n\")\n    prompt <- paste0(\n      \"RS \",\n      self$get_pid(),\n      if (frame) paste0(\" (frame \", frame, \")\"),\n      \" > \"\n    )\n    cmd <- rs__attach_get_input(prompt)\n    cmd2 <- translate_cmd(cmd)\n    if (should_quit) {\n      break\n    }\n    if (is.null(cmd2)) {\n      next\n    }\n\n    try(update_history(cmd), silent = TRUE)\n\n    ret <- self$run_with_output(\n      function(cmd, frame) {\n        dump <- as.environment(\"tools:callr\")$`__callr_data__`$.Last.dump\n        envir <- if (!frame) .GlobalEnv else dump[[frame + 12L]]\n        eval(parse(text = cmd), envir = envir)\n      },\n      list(cmd = cmd, frame = frame)\n    )\n    cat(ret$stdout)\n    cat(ret$stderr)\n    if (!is.null(ret$error)) {\n      print(ret$error)\n    } else {\n      print(ret$result)\n    }\n  }\n  invisible()\n}"

const rtdal000373Source0016 = `rs_attach <- function(self, private) {
  out <- self$get_output_connection()
  err <- self$get_error_connection()
  while (nchar(x <- processx::processx_conn_read_chars(out))) {
    cat(x)
  }
  while (nchar(x <- processx::processx_conn_read_chars(err))) {
    cat(bold(x))
  }
  tryCatch(
    {
      while (TRUE) {
        cmd <- rs__attach_get_input(paste0("RS ", self$get_pid(), " > "))
        if (cmd == ".q") {
          break
        }
        try(update_history(cmd), silent = TRUE)
        private$write_for_sure(paste0(cmd, "\n"))
        private$report_back(202, "done")
        private$attach_wait()
      }
    },
    interrupt = function(e) {
      self$interrupt()
      invisible()
    }
  )
}`

const rtdal000373Source0018 = `rs__attach_wait <- function(self, private) {
  out <- self$get_output_connection()
  err <- self$get_error_connection()
  pro <- private$pipe
  while (TRUE) {
    pr <- processx::poll(list(out, err, pro), -1)
    if (pr[[1]] == "ready") {
      if (nchar(x <- processx::processx_conn_read_chars(out))) cat(x)
    }
    if (pr[[2]] == "ready") {
      if (nchar(x <- processx::processx_conn_read_chars(err))) cat(bold(x))
    }
    if (pr[[3]] == "ready") {
      msg <- self$read()
      if (msg$code == 202) break
    }
  }
}`

const rtdal000373Source0019 = `rs__report_back <- function(self, private, code, text) {
  cmd <- paste0(
    deparse(rs__status_expr(code, text, fd = 3)),
    "\n"
  )
  private$write_for_sure(cmd)
}`

const rtdal000373Source0020 = `rs__write_for_sure <- function(self, private, text) {
  while (1) {
    text <- self$write_input(text)
    if (!length(text)) {
      break
    }
    Sys.sleep(.1)
  }
}`

const rtdal000373Source0021 = "rs__parse_msg <- function(self, private, msg) {\n  code <- as.character(msg$header$code)\n  message <- msg$body\n  if (length(message) && substr(message, 1, 8) == \"base64::\") {\n    message <- substr(message, 9, nchar(message))\n    message <- unserialize(processx::base64_decode(message))\n  } else {\n    message <- msg$header$rest\n  }\n\n  if (!code %in% names(rs__parse_msg_funcs)) {\n    throw(new_error(\"Unknown message code: `\", code, \"`\"))\n  }\n  structure(\n    rs__parse_msg_funcs[[code]](self, private, msg$header$code, message),\n    class = \"callr_session_result\"\n  )\n}"

const rtdal000373Source0023 = "rs__parse_msg_funcs[[\"200\"]] <- function(self, private, code, message) {\n  if (private$state != \"busy\") {\n    throw(new_error(\"Got `done` message when session is not busy\"))\n  }\n  private$state <- \"idle\"\n\n  res <- private$get_result_and_output()\n  c(list(code = code, message = message), res)\n}"

const rtdal000373Source0027 = `rs__parse_msg_funcs[["500"]] <- function(self, private, code, message) {
  private$state <- "finished"
  res <- private$get_result_and_output(std = TRUE)
  c(list(code = code, message = message), res)
}`

const rtdal000373Source0028 = `rs__parse_msg_funcs[["501"]] <- function(self, private, code, message) {
  private$state <- "finished"
  err <- structure(
    list(message = message),
    class = c("error", "condition")
  )
  res <- private$get_result_and_output(std = TRUE)
  res$error <- err
  c(list(code = code, message = message), res)
}`

const rtdal000373Source0030 = "rs__status_expr <- function(code, text = \"\", fd = 3L) {\n  substitute(\n    local({\n      pxlib <- as.environment(\"tools:callr\")$`__callr_data__`$pxlib\n      code_ <- code\n      fd_ <- fd\n      text_ <- text\n      data <- paste0(code_, \" 0 \", text_, \"\\n\")\n      pxlib$write_fd(as.integer(fd), data)\n    }),\n    list(code = code, fd = fd, text = text)\n  )\n}"

const rtdal000373Source0031 = "rs__prehook <- function(stdout, stderr) {\n  oexpr <- if (!is.null(stdout)) {\n    substitute(\n      {\n        assign(\n          \".__stdout__\",\n          as.environment(\"tools:callr\")$`__callr_data__`$pxlib$set_stdout_file(\n            `__fn__`\n          ),\n          envir = as.environment(\"tools:callr\")$`__callr_data__`\n        )\n      },\n      list(`__fn__` = stdout)\n    )\n  }\n  eexpr <- if (!is.null(stderr)) {\n    substitute(\n      {\n        assign(\n          \".__stderr__\",\n          as.environment(\"tools:callr\")$`__callr_data__`$pxlib$set_stderr_file(\n            `__fn__`\n          ),\n          envir = as.environment(\"tools:callr\")$`__callr_data__`\n        )\n      },\n      list(`__fn__` = stderr)\n    )\n  }\n\n  substitute(\n    {\n      o\n      e\n    },\n    list(o = oexpr, e = eexpr)\n  )\n}"

const rtdal000373Source0032 = "rs__posthook <- function(stdout, stderr) {\n  oexpr <- if (!is.null(stdout)) {\n    substitute({\n      as.environment(\"tools:callr\")$`__callr_data__`$pxlib$set_stdout(\n        as.environment(\"tools:callr\")$`__callr_data__`$.__stdout__\n      )\n    })\n  }\n  eexpr <- if (!is.null(stderr)) {\n    substitute({\n      as.environment(\"tools:callr\")$`__callr_data__`$pxlib$set_stderr(\n        as.environment(\"tools:callr\")$`__callr_data__`$.__stderr__\n      )\n    })\n  }\n\n  substitute(\n    {\n      o\n      e\n    },\n    list(o = oexpr, e = eexpr)\n  )\n}"

const rtdal000373Source0033 = `rs__get_result_and_output <- function(self, private, std) {
  ## Get stdout and stderr
  stdout <- if (
    !is.null(private$tmp_output_file) &&
      file.exists(private$tmp_output_file)
  ) {
    tryCatch(
      suppressWarnings(read_all(private$tmp_output_file)),
      error = function(e) ""
    )
  } else if (std && self$has_output_connection()) {
    tryCatch(self$read_all_output(), error = function(err) NULL)
  }
  stderr <- if (
    !is.null(private$tmp_error_file) &&
      file.exists(private$tmp_error_file)
  ) {
    tryCatch(
      suppressWarnings(read_all(private$tmp_error_file)),
      error = function(e) ""
    )
  } else if (std && self$has_error_connection()) {
    tryCatch(self$read_all_error(), error = function(err) NULL)
  }
  unlink(c(private$tmp_output_file, private$tmp_error_file))
  private$tmp_output_file <- private$tmp_error_file <- NULL

  ## Get result or error from RDS
  outp <- list(
    status = 0,
    stdout = stdout %||% "",
    stderr = stderr %||% "",
    timeout = FALSE
  )
  res <- err <- NULL
  tryCatch(
    res <- get_result(outp, private$options),
    error = function(e) err <<- e,
    interrupt = function(e) err <<- e
  )
  unlink(private$options$tmp_files, recursive = TRUE)
  private$options$tmp_files <- NULL

  ## Assemble result
  list(result = res, stdout = stdout, stderr = stderr, error = err)
}`

const rtdal000373Source0034 = `rs__handle_condition <- function(cond) {
  default_handler <- function(x) {
    classes <- class(x)
    for (cl in classes) {
      opt <- paste0("callr.condition_handler_", cl)
      if (!is.null(val <- getOption(opt)) && is.function(val)) {
        val(x)
        break
      }
    }
  }

  if (is.list(cond) && is.null(cond$muffle)) {
    cond$muffle <- "callr_r_session_muffle"
  }
  withRestarts(
    {
      signalCondition(cond)
      default_handler(cond)
    },
    callr_r_session_muffle = function() NULL,
    muffleMessage = function() NULL
  )

  invisible()
}`

const rtdal000373Source0035 = `r_session_options <- function(...) {
  update_options(r_session_options_default(), ...)
}`

const rtdal000373Source0036 = `r_session_options_default <- function() {
  list(
    func = NULL,
    args = NULL,
    libpath = .libPaths(),
    repos = default_repos(),
    stdout = NULL,
    stderr = NULL,
    error = getOption("callr.error", "error"),
    cmdargs = c(
      if (os_platform() != "windows") "--no-readline",
      "--slave",
      "--no-save",
      "--no-restore"
    ),
    system_profile = FALSE,
    user_profile = "project",
    env = c(TERM = "dumb"),
    supervise = FALSE,
    load_hook = NULL,
    extra = list(),
    arch = "same"
  )
}`

