const rtdal000378Source0001 = `rscript <- function(
  script,
  cmdargs = character(),
  libpath = .libPaths(),
  repos = default_repos(),
  stdout = NULL,
  stderr = NULL,
  poll_connection = TRUE,
  echo = FALSE,
  show = TRUE,
  callback = NULL,
  block_callback = NULL,
  spinner = FALSE,
  system_profile = FALSE,
  user_profile = "project",
  env = rcmd_safe_env(),
  timeout = Inf,
  wd = ".",
  fail_on_status = TRUE,
  color = TRUE,
  ...
) {
  load_hook <- rscript_load_hook_color(color)

  options <- convert_and_check_my_args(as.list(environment()))
  options$extra <- list(...)

  options <- setup_context(options)
  options <- setup_callbacks(options)

  options <- setup_rscript_binary_and_args(options)

  ## This cleans up everything...
  on.exit(unlink(options$tmp_files, recursive = TRUE), add = TRUE)

  if (otel::is_tracing_enabled()) {
    otel::start_local_active_span(
      "callr::rscript",
      attributes = otel::as_attributes(options)
    )
    hdrs <- otel::pack_http_context()
    names(hdrs) <- toupper(names(hdrs))
    options$env[names(hdrs)] <- hdrs
  }

  invisible(run_r(options))
}`

const rtdal000378Source0002 = "rscript_load_hook_color <- function(color) {\n  if (!color) {\n    return(\"\")\n  }\n\n  nc <- tryCatch(\n    cli::num_ansi_colors(),\n    error = function(e) 1L\n  )\n  if (nc == 1) {\n    return(\"\")\n  }\n\n  expr <- substitute(\n    options(crayon.enabled = TRUE, crayon.colors = `_nc_`),\n    list(\"_nc_\" = nc)\n  )\n  paste0(deparse(expr), \"\\n\")\n}"

const rtdal000378Source0003 = "rscript_process <- suppressMessages(R6::R6Class(\n  \"rscript_process\",\n  inherit = processx::process,\n  public = list(\n    #' @description Create a new `Rscript` process.\n    #' @param options A list of options created via\n    #'   [rscript_process_options()].\n    initialize = function(options) rscript_init(self, private, super, options),\n\n    #' @description Delete the temporary files created for this `Rscript`\n    #' process. Only call this method if you are sure that the process is\n    #' done. If you don't call this method explicitly, the temporary files\n    #' will be deleted when the process object is garbage collected.\n    cleanup = function() {\n      unlink(private$options$tmp_files, recursive = TRUE)\n    },\n\n    #' @description Clean up after an `Rscript` process, remove temporary files.\n    finalize = function() {\n      self$cleanup()\n      if (\"finalize\" %in% ls(super)) super$finalize()\n    }\n  ),\n  private = list(\n    options = NULL\n  )\n))"

const rtdal000378Source0004 = `rscript_init <- function(self, private, super, options) {
  options$load_hook <- rscript_load_hook_color(options$color)
  options <- convert_and_check_my_args(options)
  options <- setup_context(options)
  options <- setup_rscript_binary_and_args(options)

  private$options <- options

  oldwd <- getwd()
  setwd(options$wd)
  on.exit(setwd(oldwd), add = TRUE)

  pty <- isTRUE(options$extra$pty)

  with_envvar(
    options$env,
    do.call(
      super$initialize,
      c(
        list(
          options$bin,
          options$real_cmdargs,
          stdout = if (pty) NULL else options$stdout,
          stderr = if (pty) NULL else options$stderr,
          poll_connection = options$poll_connection
        ),
        options$extra
      )
    )
  )

  invisible(self)
}`

