const rtdal000384Source0002 = `remove_source <- function(x) {
  if (is.function(x)) {
    body(x) <- remove_source(body(x))
    x
  } else if (is.call(x)) {
    attr(x, "srcref") <- NULL
    attr(x, "wholeSrcref") <- NULL
    attr(x, "srcfile") <- NULL

    x[] <- lapply(x, remove_source)
    x
  } else {
    x
  }
}`

const rtdal000384Source0010 = `enumerate <- function(x) {
  if (length(x) == 0) {
    ""
  } else if (length(x) == 1) {
    x
  } else {
    l <- length(x)
    paste0(paste(x[-l], collapse = ", "), " and ", x[[l]])
  }
}`

const rtdal000384Source0011 = `crash <- function() {
  get("attach")(
    structure(
      attr(file(), "conn_id"),
      class = "UserDefinedDatabase"
    )
  )
}`

const rtdal000384Source0014 = `read_all <- function(filename) {
  con <- file(filename, open = "rb")
  on.exit(close(con), add = TRUE)
  res <- raw(0)
  while (length(more <- readBin(con, what = "raw", 10000)) && length(more)) {
    res <- c(res, more)
  }
  rawToChar(res)
}`

const rtdal000384Source0015 = `is_complete_expression <- function(x) {
  err <- NULL
  tryCatch(parse(text = x), error = function(e) err <<- e)
  if (is.null(err)) {
    return(TRUE)
  }
  exp <- tryCatch(parse(text = "1+"), error = function(e) e$message)
  exp1 <- strsplit(exp, "\n")[[1]][[1]]
  msg <- sub("^.*:\\s*([^:]+)$", "\\1", exp1, perl = TRUE)
  !grepl(msg, conditionMessage(err), fixed = TRUE)
}`

const rtdal000384Source0016 = `bold <- function(x) {
  tryCatch(
    cli::style_bold(x),
    error = function(e) x
  )
}`

const rtdal000384Source0017 = `update_history <- function(cmd) {
  tmp <- callr_tempfile("callr-hst-")
  on.exit(unlink(tmp, recursive = TRUE))
  utils::savehistory(tmp)
  cat(cmd, "\n", sep = "", file = tmp, append = TRUE)
  utils::loadhistory(tmp)
}`

