const rtdal000400Source0009 = `test_that("libpath in system, if subprocess changes R_LIBS", {
  dir.create(tmpkeep <- tempfile("keep"))
  on.exit(unlink(tmpkeep, recursive = TRUE), add = TRUE)

  rbin <- setup_r_binary_and_args(list())$bin
  rbin <- shQuote(rbin)

  f <- function(rbin, new) {
    Sys.setenv(R_LIBS = new)
    Sys.setenv(R_ENVIRON_USER = "no_such_file")
    system(
      paste(
        rbin,
        "--no-site-file --no-init-file --no-save --no-restore --slave",
        "-e \".libPaths()\""
      ),
      intern = TRUE
    )
  }

  out <- callr::r(f, list(rbin = rbin, new = tmpkeep))
  expect_true(any(grepl(basename(normalizePath(tmpkeep)), out)))

  ## Close FDs
  gc()
})`

const rtdal000400Source0010 = `test_that("libpath in system, if subprocess changes R_LIBS #2", {
  if (.Platform$OS.type != "unix") {
    skip("Unix only")
  }

  dir.create(tmpkeep <- tempfile("keep"))
  on.exit(unlink(tmpkeep, recursive = TRUE), add = TRUE)

  rbin <- setup_r_binary_and_args(list())$bin

  f <- function(rbin, new) {
    Sys.setenv(R_LIBS = new)
    Sys.setenv(R_ENVIRON_USER = "no_such_file")
    env <- paste0("R_LIBS=", shQuote(new))
    tmp <- tempfile()
    on.exit(unlink(tmp), add = TRUE)
    system2(
      rbin,
      c(
        "--no-site-file",
        "--no-init-file",
        "--no-save",
        "--no-restore",
        "--slave",
        "-e",
        "'.libPaths()'"
      ),
      env = env,
      stdout = tmp
    )
    readLines(tmp)
  }

  out <- callr::r(f, list(rbin = rbin, new = tmpkeep))
  expect_true(any(grepl(basename(normalizePath(tmpkeep)), out)))

  ## Close FDs
  gc()
})`

const rtdal000400Source0011 = `test_that("libpath = NULL keeps the subprocess library path of a fresh R session", {
  # See https://github.com/r-lib/callr/issues/255
  skip_in_covr()
  skip_if_not_installed("withr")

  dir.create(tmp_lib <- tempfile())
  dir.create(tmp_wd <- tempfile())
  on.exit(unlink(c(tmp_lib, tmp_wd), recursive = TRUE), add = TRUE)

  cat(
    sprintf(".libPaths(c(%s, .libPaths()))\n", deparse(tmp_lib)),
    file = file.path(tmp_wd, ".Rprofile")
  )

  # With libpath = NULL the subprocess respects .libPaths() set from the
  # project .Rprofile, instead of overwriting it with the parent's libpath.
  lp_null <- withr::with_dir(
    tmp_wd,
    r(
      function() .libPaths(),
      libpath = NULL,
      user_profile = "project"
    )
  )
  expect_true(normalizePath(tmp_lib) %in% normalizePath(lp_null))

  # Sanity check: with the default libpath, callr would overwrite the
  # libpath set in the project .Rprofile.
  lp_default <- withr::with_dir(
    tmp_wd,
    r(
      function() .libPaths(),
      user_profile = "project"
    )
  )
  expect_false(normalizePath(tmp_lib) %in% normalizePath(lp_default))

  gc()
})`

const rtdal000400Source0012 = `test_that("setting profile/environ variables in 'env'", {
  # See https://github.com/r-lib/callr/issues/193

  skip_in_covr()

  profile <- tempfile()
  on.exit(unlink(profile), add = TRUE)
  cat("foo <- '11'\n", file = profile)

  envfile <- tempfile()
  on.exit(unlink(envfile), add = TRUE)
  cat("MY_ENV2=MILES2\n", file = envfile)

  ret <- callr::r(
    function() {
      c(
        Sys.getenv("MY_ENV"),
        Sys.getenv("R_PROFILE_USER"),
        exists("foo"),
        Sys.getenv("MY_ENV2")
      )
    },
    user_profile = TRUE,
    env = c(
      "R_PROFILE_USER" = profile,
      "R_ENVIRON_USER" = envfile,
      "MY_ENV" = "MILES"
    )
  )

  expect_equal(ret, c("MILES", profile, "TRUE", "MILES2"))
})`

