const rtdal000415Source0001 = `test_that("rscript", {
  out <- rscript("fixtures/script.R", show = FALSE)
  expect_equal(out$status, 0L)
  expect_equal(
    out$stdout,
    if (os_platform() == "windows") "stdout\r\n" else "stdout\n"
  )
  expect_equal(
    out$stderr,
    if (os_platform() == "windows") "stderr\r\n" else "stderr\n"
  )
  gc()
})`

const rtdal000415Source0002 = `test_that("rscript_process", {
  px <- rscript_process$new(
    rscript_process_options(script = "fixtures/script.R")
  )
  on.exit(try(px$kill(), silent = TRUE), add = TRUE)
  px$wait(5000)

  expect_equal(px$get_exit_status(), 0)
  expect_equal(px$read_output_lines(), "stdout")
  expect_equal(px$read_error_lines(), "stderr")
  rm(px)
  gc()
})`

const rtdal000415Source0003 = `test_that("stderr -> stdout", {
  out <- rscript("fixtures/script2.R", show = FALSE, stderr = "2>&1")
  exp <- if (os_platform() == "windows") {
    "out1err1out2err2\r\n"
  } else {
    "out1err1out2err2\n"
  }
  expect_equal(out$stdout, exp)
  expect_null(out$stderr)

  out2 <- test_temp_file(create = FALSE)
  rscript("fixtures/script2.R", show = FALSE, stdout = out2, stderr = out2)
  expect_equal(readLines(out2), "out1err1out2err2")
  gc()
})`

const rtdal000415Source0004 = `test_that("stdout = '|' does not hang when child errors (#313)", {
  skip_on_cran()
  tmp <- test_temp_file(create = FALSE)
  writeLines("stop('test error')", tmp)

  setTimeLimit(elapsed = 30, transient = TRUE)
  on.exit(setTimeLimit(), add = TRUE)

  res <- rscript(
    tmp,
    show = FALSE,
    fail_on_status = FALSE,
    timeout = 5,
    stdout = "|",
    stderr = "2>&1"
  )

  expect_false(res$timeout)
  expect_equal(res$status, 1L)
  expect_match(res$stdout, "test error")
  expect_null(res$stderr)
  gc()
})`

const rtdal000415Source0005 = `test_that("pty = TRUE merges stderr into stdout and sets a tty", {
  skip_on_cran()

  tmp <- test_temp_file(create = FALSE)
  writeLines(
    c(
      "cat('isatty:', isatty(stdout()), '\\n')",
      "message('err line')",
      "cat('out line\\n')"
    ),
    tmp
  )

  res <- rscript(tmp, pty = TRUE, show = FALSE)
  expect_equal(res$status, 0L)
  expect_null(res$stderr)
  ## ConPTY on Windows interleaves CSI mode-change escapes with output;
  ## strip them before matching.
  out <- cli::ansi_strip(res$stdout)
  out <- sub("\033.*\a", "", out)
  expect_match(out, "isatty: TRUE")
  expect_match(out, "err line")
  expect_match(out, "out line")
})`

const rtdal000415Source0006 = "test_that(\"pty = TRUE rejects a non-null stderr\", {\n  skip_on_cran()\n\n  tmp <- test_temp_file(create = FALSE)\n  writeLines(\"cat('hi\\\\n')\", tmp)\n\n  expect_error(\n    rscript(tmp, pty = TRUE, stderr = \"err.txt\", show = FALSE),\n    \"`stderr` cannot be set when `pty = TRUE`\"\n  )\n})"

const rtdal000415Source0007 = `test_that("rscript_process supports pty = TRUE", {
  skip_on_cran()

  tmp <- test_temp_file(create = FALSE)
  writeLines(
    c("message('on stderr')", "cat('on stdout\\n')"),
    tmp
  )

  opts <- rscript_process_options(script = tmp, extra = list(pty = TRUE))
  px <- rscript_process$new(opts)
  on.exit(try(px$kill(), silent = TRUE), add = TRUE)
  px$wait(5000)

  expect_false(px$has_error_connection())
  out <- cli::ansi_strip(px$read_all_output())
  out <- sub("\033.*\a", "", out)
  expect_match(out, "on stderr")
  expect_match(out, "on stdout")
})`

const rtdal000415Source0008 = `test_that("cleans up temporary files", {
  skip_on_cran()

  rsc <- function() {
    library(callr)
    scriptfile <- tempfile(fileext = ".R")
    cat("cat('foobar')\n", file = scriptfile)

    old <- dir(tempdir(), pattern = "^callr-")

    result <- callr::rscript(scriptfile)

    new <- setdiff(dir(tempdir(), "^callr-"), old)

    list(result = result, new = new)
  }

  out <- r(rsc)
  expect_identical(out$result$stdout, "foobar")
  expect_identical(out$new, character())
})`

const rtdal000415Source0009 = `test_that("bg process cleans up temporary files", {
  skip_on_cran()

  rsc <- function() {
    library(callr)
    scriptfile <- tempfile(fileext = ".R")
    cat("cat('foobar')\n", file = scriptfile)

    old <- dir(tempdir(), pattern = "^callr-")

    opts <- rscript_process_options(script = scriptfile)
    rp <- rscript_process$new(opts)
    on.exit(tryCatch(rp$kill, error = function(e) NULL), add = TRUE)
    rp$wait(5000)
    result <- rp$read_output()
    rp$kill()

    rm(rp)
    gc()
    gc()
    new <- setdiff(dir(tempdir(), "^callr-"), old)

    list(result = result, new = new)
  }

  out <- r(rsc)
  expect_identical(out$result, "foobar")
  expect_identical(out$new, character())
})`

