const rtdal000440Source0001 = `setup_app <- function() {
  theme <- list("url" = list(color = "blue"))
  app <- cliapp::start_app(theme = theme, output = "stdout")
}`

const rtdal000440Source0002 = `load_packages <- function() {
  tryCatch(
    {
      library(cliapp)
      library(async)
      library(docopt)
    },
    error = function(e) {
      cli_alert_danger(
        "The {.pkg async} and {.pkg docopt} packages are needed!"
      )
      q(save = "no", status = 1)
    }
  )
}`

const rtdal000440Source0003 = `up <- function(urls, timeout = 5) {
  load_packages()
  setup_app()
  chk_url <- async(function(url, ...) {
    http_head(url, ...)$then(function(res) {
      if (res$status_code < 300) {
        cli_alert_success("{.url {url}} ({res$times[['total']]}s)")
      } else {
        cli_alert_danger("{.url {url}} (HTTP {res$status_code})")
      }
    })$catch(error = function(err) {
      e <- if (grepl("timed out", err$message)) "timed out" else "error"
      cli_alert_danger("{.url {url}} ({e})")
    })
  })

  invisible(synchronise(
    async_map(urls, chk_url, options = list(timeout = timeout))
  ))
}`

