const rtdal000453Source0029 = `ansi_grep <- function(
  pattern,
  x,
  ignore.case = FALSE,
  perl = FALSE,
  value = FALSE,
  ...
) {
  # if value = FALSE, then we want to return the original values as
  # ansi strings, so we need to special case that
  if (value) {
    idx <- ansi_grep(
      pattern,
      x,
      ignore.case = ignore.case,
      perl = perl,
      value = FALSE,
      ...
    )
    ansi_string(x[idx])
  } else {
    ansi_grep_internal(
      grep,
      pattern,
      x,
      ignore.case = ignore.case,
      perl = perl,
      value = value,
      ...
    )
  }
}`

const rtdal000453Source0030 = `ansi_grepl <- function(pattern, x, ...) {
  ansi_grep_internal(grepl, pattern, x, ...)
}`

const rtdal000453Source0031 = `ansi_grep_internal <- function(fun, pattern, x, ...) {
  pattern <- ansi_strip(pattern)
  x <- ansi_strip(x)
  fun(pattern, x, ...)
}`

const rtdal000453Source0032 = `ansi_nzchar <- function(x, ...) {
  x <- ansi_strip(x)
  nzchar(x, ...)
}`

