const rtdal000466Source0001 = `cli_debug_doc <- function(app = default_app() %||% start_app()) {
  tgs <- vcapply(app$doc, "[[", "tag")
  ids <- vcapply(app$doc, "[[", "id")
  cls <- vcapply(app$doc, function(x) paste(x$class, collapse = " "))
  thm <- lapply(app$doc, function(x) x$theme)

  df <- data.frame(
    stringsAsFactors = FALSE,
    tag = tgs,
    id = ids,
    class = cls,
    theme = I(as.list(thm)),
    styles = I(as.list(unname(app$styles)))
  )

  class(df) <- c("cli_doc", class(df))
  df
}`

const rtdal000466Source0002 = `format.cli_doc <- function(x, ...) {
  nz <- nrow(x) > 0
  c(
    "<cli document>",
    paste0(
      if (nz) "<",
      x$tag,
      if (nz) " id=\"",
      x$id,
      if (nz) "\"",
      ifelse(x$class == "", "", paste0(" class=\"", x$class, "\"")),
      if (nz) ">",
      ifelse(vlapply(x$theme, is.null), "", " +theme")
    )
  )
}`

const rtdal000466Source0003 = `print.cli_doc <- function(x, ...) {
  cat(format(x, ...), sep = "\n")
  invisible(x)
}`

