const rtdal000468Source0001 = `diff_chr <- function(old, new, max_dist = Inf) {
  stopifnot(
    is.character(old),
    is.character(new),
    max_dist == Inf || is_count(max_dist)
  )
  max_dist2 <- as_max_dist(max_dist)

  lcs <- .Call(clic_diff_chr, old, new, max_dist2)

  if (max_dist2 != 0 && lcs[[4]] == max_dist2) {
    throw(cli_error(
      "Diff edit distance is larger than the limit.",
      "i" = "The edit distance limit is {max_dist}.",
      .data = list(max_dist = max_dist),
      .class = "cli_diff_max_dist"
    ))
  }

  op <- c("match", "delete", "insert")[lcs[[1]]]
  lcs <- data.frame(
    stringsAsFactors = FALSE,
    operation = op,
    offset = lcs[[2]],
    length = lcs[[3]],
    old_offset = cumsum(ifelse(op == "insert", 0, lcs[[3]])),
    new_offset = cumsum(ifelse(op == "delete", 0, lcs[[3]]))
  )

  ret <- structure(
    list(old = old, new = new, lcs = lcs),
    class = c("cli_diff_chr", "cli_diff", "list")
  )

  ret
}`

const rtdal000468Source0002 = `diff_str <- function(old, new, max_dist = Inf) {
  stopifnot(
    is_string(old),
    is_string(new)
    # max_dist is checked in diff_chr
  )

  old1 <- utf8_graphemes(old)[[1]]
  new1 <- utf8_graphemes(new)[[1]]

  ret <- diff_chr(old1, new1, max_dist)

  class(ret) <- c("cli_diff_str", class(ret))

  ret
}`

const rtdal000468Source0003 = "format.cli_diff_chr <- function(x, context = 3L, ...) {\n  stopifnot(context == Inf || is_count(context))\n  if (length(list(...)) > 0) {\n    warning(\"Extra arguments were ignored in `format.cli_diff_chr()`.\")\n  }\n\n  chunks <- get_diff_chunks(x$lcs, context = context)\n  out <- lapply(\n    seq_len(nrow(chunks)),\n    format_chunk,\n    x = x,\n    chunks = chunks,\n    context = context\n  )\n\n  ret <- as.character(unlist(out))\n  if (context == Inf && length(ret) > 0) ret <- ret[-1]\n\n  ret\n}"

const rtdal000468Source0004 = "get_diff_chunks <- function(lcs, context = 3L) {\n  # the number of chunks is the number of non-matching sequences if\n  # context == 0, but short matching parts do not separate chunks\n  runs <- rle(lcs$operation != \"match\" | lcs$length <= 2 * context)\n  nchunks <- sum(runs$values)\n\n  # special case for a single match chunk\n  if (nrow(lcs) == 1 && lcs$operation == \"match\") {\n    nchunks <- if (context == Inf) 1 else 0\n  }\n\n  chunks <- data.frame(\n    op_begin = integer(nchunks), # first op in chunk\n    op_length = integer(nchunks), # number of operations in chunk\n    old_begin = integer(nchunks), # first line from `old` in chunk\n    old_length = integer(nchunks), # number of lines from `old` in chunk\n    new_begin = integer(nchunks), # first line from `new` in chunk\n    new_length = integer(nchunks) # number of lines from `new` in chunk\n  )\n\n  if (nchunks == 0) return(chunks)\n\n  # infer some data about the original diff input\n  old_off <- c(0, lcs$old_offset)\n  new_off <- c(0, lcs$new_offset)\n  old_size <- old_off[length(old_off)]\n  new_size <- new_off[length(new_off)]\n  old_empty <- old_size == 0\n  new_empty <- new_size == 0\n\n  # avoid working with Inf\n  if (context == Inf) context <- max(old_size, new_size)\n\n  # chunk starts at operation number sum(length) before it, plus 1, but\n  # at the end we change this to include the context chunks are well\n  chunks$op_begin <- c(0, cumsum(runs$lengths))[which(runs$values)] + 1\n  chunks$op_length <- runs$lengths[runs$values]\n\n  # `old` positions are from `old_off`, but need to fix the boundaries\n  chunks$old_begin <- old_off[chunks$op_begin] - context + 1\n  chunks$old_begin[chunks$old_begin <= 1] <- if (old_empty) 0 else 1\n  old_end <- old_off[chunks$op_begin + chunks$op_length] + context\n  old_end[old_end > old_size] <- old_size\n  chunks$old_length <- old_end - chunks$old_begin + 1\n\n  # `new` positions are similar\n  chunks$new_begin <- new_off[chunks$op_begin] - context + 1\n  chunks$new_begin[chunks$new_begin <= 1] <- if (new_empty) 0 else 1\n  new_end <- new_off[chunks$op_begin + chunks$op_length] + context\n  new_end[new_end > new_size] <- new_size\n  chunks$new_length <- new_end - chunks$new_begin + 1\n\n  # change to include context chunks\n  if (context > 0) {\n    # calculate the end before updating the begin\n    op_end <- chunks$op_begin + chunks$op_length - 1 + 1\n    op_end[op_end > nrow(lcs)] <- nrow(lcs)\n    chunks$op_begin <- chunks$op_begin - 1\n    chunks$op_begin[chunks$op_begin == 0] <- 1\n    chunks$op_length <- op_end - chunks$op_begin + 1\n  }\n\n  chunks\n}"

const rtdal000468Source0005 = `format_chunk <- function(x, chunks, num, context) {
  hdr <- paste0(
    "@@ -",
    chunks$old_begin[num],
    if ((l <- chunks$old_length[num]) != 1) paste0(",", l),
    " +",
    chunks$new_begin[num],
    if ((l <- chunks$new_length[num]) != 1) paste0(",", l),
    " @@"
  )

  from <- chunks$op_begin[num]
  to <- chunks$op_begin[num] + chunks$op_length[num] - 1

  lines <- lapply(from:to, function(i) {
    op <- x$lcs$operation[i]
    off <- x$lcs$offset[i]
    len <- x$lcs$length[i]
    if (op == "match") {
      if (len > context) {
        if (i == from) {
          # start later
          off <- off + len - context
          len <- context
        } else {
          # finish earlier
          len <- context
        }
      }
      paste0(" ", x$old[off + 1:len])
    } else if (op == "delete") {
      col_blue(paste0("-", x$old[off + 1:len]))
    } else if (op == "insert") {
      col_green(paste0("+", x$new[off + 1:len]))
    }
  })
  c(hdr, lines)
}`

const rtdal000468Source0006 = `print.cli_diff_chr <- function(x, ...) {
  writeLines(format(x, ...))
}`

const rtdal000468Source0007 = "format.cli_diff_str <- function(x, ...) {\n  if (length(list(...)) > 0) {\n    warning(\"Extra arguments were ignored in `format.cli_diff_chr()`.\")\n  }\n\n  if (num_ansi_colors() == 1) {\n    format_diff_str_nocolor(x, ...)\n  } else {\n    format_diff_str_color(x, ...)\n  }\n}"

const rtdal000468Source0008 = `format_diff_str_color <- function(x, ...) {
  out <- lapply(seq_len(nrow(x$lcs)), function(i) {
    op <- x$lcs$operation[i]
    off <- x$lcs$offset[i]
    len <- x$lcs$length[i]
    if (op == "match") {
      paste0(x$old[off + 1:len], collapse = "")
    } else if (op == "delete") {
      bg_blue(col_black(paste0(x$old[off + 1:len], collapse = "")))
    } else if (op == "insert") {
      bg_green(col_black(paste0(x$new[off + 1:len], collapse = "")))
    }
  })

  paste(out, collapse = "")
}`

const rtdal000468Source0009 = `format_diff_str_nocolor <- function(x, ...) {
  out <- lapply(seq_len(nrow(x$lcs)), function(i) {
    op <- x$lcs$operation[i]
    off <- x$lcs$offset[i]
    len <- x$lcs$length[i]
    if (op == "match") {
      paste0(x$old[off + 1:len], collapse = "")
    } else if (op == "delete") {
      paste0(c("[-", x$old[off + 1:len], "-]"), collapse = "")
    } else if (op == "insert") {
      paste0(c("{+", x$new[off + 1:len], "+}"), collapse = "")
    }
  })

  paste(out, collapse = "")
}`

const rtdal000468Source0010 = `as_max_dist <- function(max_dist) {
  if (max_dist == Inf) {
    0L
  } else {
    as.integer(max_dist + 1L)
  }
}`

