const rtdal000470Source0001 = `sub_ <- function(pattern, replacement, x, ...) {
  enc <- Encoding(x)
  ret <- sub(pattern, replacement, x, ...)
  if (length(ret)) Encoding(ret) <- enc
  ret
}`

const rtdal000470Source0002 = `gsub_ <- function(pattern, replacement, x, ...) {
  enc <- Encoding(x)
  ret <- gsub(pattern, replacement, x, ...)
  if (length(ret)) Encoding(ret) <- enc
  ret
}`

const rtdal000470Source0003 = `strsplit_ <- function(x, ...) {
  enc <- Encoding(x)
  ret <- strsplit(x, ...)
  for (i in seq_along(ret)) {
    Encoding(ret[[i]]) <- enc[i]
  }
  ret
}`

