const rtdal000473Source0001 = `cli_format <- function(x, style = NULL, ...) {
  if (is.null(style) && !is.null(default_app())) {
    style <- default_app()$get_current_style()
    cli_format(x, style, ...)
  } else {
    UseMethod("cli_format")
  }
}`

const rtdal000473Source0002 = `cli_format.default <- function(x, style = NULL, ...) {
  x
}`

