const rtdal000477Source0001 = `if (getRversion() >= "2.15.1") utils::globalVariables("app")`

const rtdal000477Source0004 = "inline_transformer <- function(code, envir) {\n  app <- envir$app\n\n  match <- regexpr(inline_regex(), code, perl = TRUE)\n  has_style <- match != -1\n\n  if (has_style) {\n    # styling\n    starts <- attr(match, \"capture.start\")\n    ends <- starts + attr(match, \"capture.length\") - 1L\n    captures <- substring(code, starts, ends)\n    funname <- captures[[1]]\n    text <- captures[[2]]\n\n    id <- clii__container_start(app, \"span\", class = funname)\n    on.exit(clii__container_end(app, id), add = TRUE)\n\n    # If we don't have a brace expression, then we add another class-less\n    # `<span>` here, because this will be the one replaced by the pure\n    # substitutions (the other branch of the `if`). This ensures that\n    # (non-inherited) styling will _not_ be applied before collapsing them,\n    # but only to the whole non-brace expression. We don't need to end this\n    # container, because the one above (`id`) will end this one as well.\n\n    braceexp <- grepl(\"^[<][^.][^}]*[>]$\", text) &&\n      count_brace_exp(text, .open = \"<\", .close = \">\") == 1\n    if (!braceexp) {\n      id2 <- clii__container_start(app, \"span\", class = NULL)\n    }\n\n    out <- glue(\n      text,\n      .envir = envir,\n      .transformer = inline_transformer,\n      .open = paste0(\"<\", envir$marker),\n      .close = paste0(envir$marker, \">\")\n    )\n\n    # If we don't have a brace expression, then (non-inherited) styling was\n    # not applied internally, and we need to apply it now. We also need to\n    # end the dummy class-less `<span>` here, so we use the original styled\n    # contained (`id`).\n\n    if (!braceexp) {\n      clii__container_end(app, id2)\n      style <- app$get_current_style()\n      out <- inline_generic(app, out, style)\n    }\n\n    out\n  } else {\n    # plain substitution\n    expr <- parse(text = code, keep.source = FALSE)\n    val <- eval(expr, envir = envir)\n\n    # If we are inside another `<span>`, then we'll \"replace\" that with a\n    # new one, so we can add extra classes (from `class-map`) and styles\n    # (from [cli_vec()] to it. Replacing means that we look up the right\n    # classes and the id, end the container, and create another one with\n    # the same classes (+ from `class_map`), the same id, and potentially\n    # the styles from [cli_vec()].\n    #\n    # If we are not inside another `<span>`, then we'll just add a\n    # class-less span, so that the non-inherited styles (e.g. `before`) are\n    # not used before collapsing.\n\n    node <- utils::tail(app$doc, 1)[[1]]\n    if (node$tag == \"span\") {\n      class <- node$class\n      id <- node$id\n      clii__container_end(app, id = node$id)\n    } else {\n      class <- NULL\n      id <- NULL\n    }\n\n    rcls <- class(val)\n    stls <- app$get_current_style()$`class-map`\n    cls <- na.omit(match(rcls, names(stls)))[1]\n    if (!is.na(cls)) class <- c(class, stls[[cls]])\n\n    vec_style <- attr(val, \"cli_style\")\n    tid <- if (!is.null(vec_style)) {\n      app$add_theme(list(span = vec_style))\n    }\n\n    id <- clii__container_start(\n      app,\n      \"span\",\n      id = id,\n      class = paste(class, collapse = \" \"),\n      theme = tid\n    )\n    # We don't need to end the replacement container, that happens upstream.\n    if (node$tag != \"span\") {\n      on.exit(clii__container_end(app, id), add = TRUE)\n    }\n\n    style <- app$get_current_style()\n    inline_collapse(\n      inline_generic(app, val, style = style),\n      style = style\n    )\n  }\n}"

const rtdal000477Source0005 = `clii__inline <- function(app, text, .list) {
  ## Inject that app, so we can style
  texts <- c(if (!is.null(text)) list(text), .list)
  out <- lapply(texts, function(t) {
    t$values$app <- app
    glue(
      t$str,
      .envir = t$values,
      .transformer = inline_transformer,
      .open = paste0("<", t$values$marker),
      .close = paste0(t$values$marker, ">"),
      .trim = FALSE
    )
  })
  paste(out, collapse = "")
}`

const rtdal000477Source0007 = `make_cmd_transformer <- function(values, .call = NULL) {
  values$marker <- random_id()
  values$qty <- NA_integer_
  values$num_subst <- 0L
  values$postprocess <- FALSE
  values$pmarkers <- list()

  # These are common because of purrr's default argument names, so we
  # hardcode them es exceptions. They are in packages
  # crossmap, crosstable, rstudio.prefs, rxode2, starter.
  # rxode2 has the other ones, and we should fix that in rxode2
  # the function calls are in the oolong packagee, need to fix this as well.
  exceptions <- c(
    ".x",
    ".y",
    ".",
    ".md",
    ".met",
    ".med",
    ".mul",
    ".muR",
    ".dir",
    ".muU",
    ".sym_flip(bool_word)",
    ".sym_flip(bool_topic)",
    ".sym_flip(bool_wsi)"
  )

  # it is not easy to do better than this, we would need to pass a call
  # down from the exported functions

  caller <- .call %||% sys.call(-1)
  function(code, envir) {
    first_char <- substr(code, 1, 1)

    # {?} pluralization
    if (first_char == "?") {
      parse_plural(code, values)

      # {.} cli style
    } else if (first_char == "." && !code %in% exceptions) {
      m <- regexpr(inline_regex(), code, perl = TRUE)
      has_match <- m != -1
      if (!has_match) {
        throw(cli_error(
          call. = caller,
          "Invalid cli literal: {.code {{{abbrev(code, 10)}}}} starts with a dot.",
          "i" = "Interpreted literals must not start with a dot in cli >= 3.4.0.",
          "i" = paste(
            "{.code {{}}} expressions starting with a dot are",
            "now only used for cli styles."
          ),
          "i" = paste(
            "To avoid this error, put a space character after",
            "the starting {.code {'{'}} or use parentheses:",
            "{.code {{({abbrev(code, 10)})}}}."
          )
        ))
      }

      starts <- attr(m, "capture.start")
      ends <- starts + attr(m, "capture.length") - 1L
      captures <- substring(code, starts, ends)
      funname <- captures[[1]]
      text <- captures[[2]]

      out <- glue(
        text,
        .envir = envir,
        .transformer = sys.function(),
        .cli = TRUE
      )
      paste0("<", values$marker, ".", funname, " ", out, values$marker, ">")

      # {} plain substitution
    } else {
      expr <- parse(text = code, keep.source = FALSE) %??%
        cli_error(
          call. = caller,
          "Could not parse cli {.code {{}}} expression:
           {.code {abbrev(code, 20)}}."
        )
      res <- eval(expr, envir = envir) %??%
        cli_error(
          call. = caller,
          "Could not evaluate cli {.code {{}}} expression:
           {.code {abbrev(code, 20)}}."
        )

      id <- paste0("v", length(values))
      values[[id]] <- res
      values$qty <- if (length(res) == 0) 0 else res
      values$num_subst <- values$num_subst + 1L
      paste0("<", values$marker, id, values$marker, ">")
    }
  }
}`

const rtdal000477Source0008 = `glue_cmd <- function(..., .envir, .call = sys.call(-1), .trim = TRUE) {
  str <- paste0(unlist(list(...), use.names = FALSE), collapse = "")
  values <- new.env(parent = emptyenv())
  transformer <- make_cmd_transformer(values, .call = .call)
  pstr <- glue(
    str,
    .envir = .envir,
    .transformer = transformer,
    .cli = TRUE,
    .trim = .trim
  )
  glue_delay(
    str = post_process_plurals(pstr, values),
    values = values
  )
}`

const rtdal000477Source0009 = `glue_no_cmd <- function(...) {
  str <- paste0(unlist(list(...), use.names = FALSE), collapse = "")
  values <- new.env(parent = emptyenv())
  glue_delay(
    str = str,
    values = values
  )
}`

