const rtdal000485Source0002 = `make_quantity <- function(object) {
  val <- if (is.numeric(object)) {
    stopifnot(length(object) == 1)

    if (is.finite(object)) as.integer(object) else object
  } else {
    length(object)
  }
}`

const rtdal000485Source0004 = `as.character.cli_no <- function(x, ...) {
  if (make_quantity(x) == 0) "no" else as.character(unclass(x))
}`

const rtdal000485Source0006 = `as.character.cli_noprint <- function(x, ...) {
  ""
}`

const rtdal000485Source0007 = `parse_plural <- function(code, values) {
  # If we have the quantity already, then process it now.
  # Otherwise we put in a marker for it, and request post-processing.
  qty <- make_quantity(values$qty)
  if (!is.na(qty)) {
    process_plural(qty, code)
  } else {
    values$postprocess <- TRUE
    id <- random_id()
    values$pmarkers[[id]] <- code
    id
  }
}`

const rtdal000485Source0008 = "process_plural <- function(qty, code) {\n  parts <- strsplit(str_tail(code), \"/\", fixed = TRUE)[[1]]\n  if (last_character(code) == \"/\") parts <- c(parts, \"\")\n  if (length(parts) == 1) {\n    if (is.finite(qty) & qty == 1) \"\" else parts[1]\n  } else if (length(parts) == 2) {\n    if (is.finite(qty) & qty == 1) parts[1] else parts[2]\n  } else if (length(parts) == 3) {\n    if (is.finite(qty) & qty == 0) {\n      parts[1]\n    } else if (is.finite(qty) & qty == 1) {\n      parts[2]\n    } else {\n      parts[3]\n    }\n  } else {\n    stop(\"Invalid pluralization directive: `\", code, \"`\")\n  }\n}"

const rtdal000485Source0010 = `pluralize <- function(
  ...,
  .envir = parent.frame(),
  .transformer = glue::identity_transformer
) {
  values <- new.env(parent = emptyenv())
  values$empty <- random_id()
  values$qty <- values$empty
  values$num_subst <- 0L
  values$postprocess <- FALSE
  values$pmarkers <- list()

  tf <- function(text, envir) {
    if (substr(text, 1, 1) == "?") {
      if (identical(values$qty, values$empty)) {
        values$postprocess <- TRUE
        id <- random_id()
        values$pmarkers[[id]] <- text
        return(id)
      } else {
        return(process_plural(make_quantity(values$qty), text))
      }
    } else {
      values$num_subst <- values$num_subst + 1
      qty <- .transformer(text, envir)
      values$qty <- qty
      return(inline_collapse(qty))
    }
  }

  raw <- glue::glue(..., .envir = .envir, .transformer = tf, .comment = "")
  post_process_plurals(raw, values)
}`

