const rtdal000488Source0001 = `cli_progress_along <- function(
  x,
  name = NULL,
  total = length(x),
  ...,
  .envir = parent.frame()
) {
  name
  total
  .envir
  list(...)

  if (getRversion() < "3.5.0") return(seq_along(x))
  id <- cli_progress_bar(
    name = name,
    total = total,
    ...,
    .auto_close = FALSE,
    .envir = .envir
  )
  closeenv <- sys.frame(-1)
  if (format(closeenv) != clienv$globalenv) {
    defer(
      cli_progress_done(id = id, .envir = .envir, result = "auto"),
      envir = closeenv
    )
  }
  sax <- seq_along(x)
  clienv$progress[[id]]$caller <- .envir
  .Call(clic_progress_along, sax, clienv$progress[[id]])
}`

const rtdal000488Source0002 = `progress_altrep_update <- function(pb) {
  tryCatch(
    {
      cli_tick_reset()
      caller <- pb$caller
      pb$tick <- pb$tick + 1L

      if (is.null(pb$format)) {
        pb$format <- pb__default_format(pb$type, pb$total)
      }

      opt <- options(cli__pb = pb)
      on.exit(options(opt), add = TRUE)

      handlers <- cli_progress_select_handlers(pb, caller)
      if (is.null(pb$added)) {
        pb$added <- TRUE
        for (h in handlers) {
          if ("add" %in% names(h)) h$add(pb, .envir = caller)
        }
      } else {
        for (h in handlers) {
          if ("set" %in% names(h)) h$set(pb, .envir = caller)
        }
      }
    },
    error = function(err) {
      if (!isTRUE(pb$warned)) {
        warning(
          "cli progress bar update failed: ",
          conditionMessage(err),
          immediate. = TRUE
        )
      }
      pb$warned <- TRUE
    }
  )

  NULL
}`

